static int to_upper_case(uint8_t* p) {
  if (p[0] < 0xC0) {
    if (p[0] >= 'a' && p[0] <= 'z') p[0] ^= 32;
    return 1;
  }
  if (p[0] < 0xE0) {
    p[1] ^= 32;
    return 2;
  }
  p[2] ^= 5;
  return 3;
}

int br_transform_dictionary_word(uint8_t* dst, const uint8_t* word, int len, int transform) {
  int idx = 0;
  const BrTransform* t = &kBrotliTransforms[transform];
  const char* prefix = t->prefix;
  const char* suffix = t->suffix;
  int type = t->type;
  int skip = type >= BR_TRANSFORM_OMIT_FIRST_1 ? (type - BR_TRANSFORM_OMIT_FIRST_1 + 1) : 0;
  int i = 0;
  while (*prefix) dst[idx++] = (uint8_t)*prefix++;
  if (skip > len) skip = len;
  word += skip;
  len -= skip;
  if (type >= BR_TRANSFORM_OMIT_LAST_1 && type <= BR_TRANSFORM_OMIT_LAST_9) {
    len -= (type - BR_TRANSFORM_OMIT_LAST_1 + 1);
  }
  {
    uint8_t* uppercase = &dst[idx];
    while (i < len) dst[idx++] = word[i++];
    if (type == BR_TRANSFORM_UPPERCASE_FIRST) {
      if (len > 0) to_upper_case(uppercase);
    } else if (type == BR_TRANSFORM_UPPERCASE_ALL) {
      int l = len;
      while (l > 0) {
        int step = to_upper_case(uppercase);
        uppercase += step;
        l -= step;
      }
    }
  }
  while (*suffix) dst[idx++] = (uint8_t)*suffix++;
  return idx;
}
