/* Brotli decoder (RFC 7932 + large-window extension + raw compound dictionary).
   Written from the specification and observed behaviour. */
#include "decode.h"
#include "../common/platform.h"
#include "../common/dictionary.h"
#include "../common/transform.h"
#include "../common/context.h"
#include "../common/prefix.h"
#include <setjmp.h>
#include <stdio.h>

typedef struct {
  uint8_t bits;
  uint16_t value;
} HuffmanCode;

#define HUFFMAN_ROOT_BITS 8

typedef struct {
  HuffmanCode* codes;   /* storage for all tables */
  HuffmanCode** htrees; /* pointers to each tree's root */
  uint32_t alphabet_size_max;
  uint32_t alphabet_size_limit;
  uint32_t num_htrees;
  size_t cap;
  size_t used;
} HuffmanTreeGroup;

typedef struct {
  const BrDecoderIO* io;
  jmp_buf jb;
  int error;

  /* bit reader */
  uint64_t acc;
  uint32_t nbits;
  const uint8_t* next;
  size_t avail;
  int eof;
  size_t total_in;

  /* stream state */
  int window_bits;
  int large_window;
  int max_backward_distance;
  int max_distance;

  uint8_t* ringbuffer;
  int ringbuffer_size;
  int ringbuffer_mask;
  int new_ringbuffer_size;
  int pos;
  size_t partial_pos_out; /* written to output */
  int rb_roundtrips;

  int meta_block_remaining_len;
  int is_last_metablock;
  int is_uncompressed;
  int is_metadata;

  int dist_rb[4];
  int dist_rb_idx;

  /* per-metablock */
  uint32_t num_block_types[3];
  uint32_t block_length[3];
  uint32_t block_type_rb[6];
  HuffmanCode* block_type_trees[3];
  HuffmanCode* block_len_trees[3];
  uint32_t distance_postfix_bits;
  uint32_t num_direct_distance_codes;
  uint32_t distance_postfix_mask;
  uint8_t* context_modes;
  uint8_t* context_map;
  uint8_t* dist_context_map;
  uint32_t num_literal_htrees;
  uint32_t num_dist_htrees;
  HuffmanTreeGroup literal_hgroup;
  HuffmanTreeGroup insert_copy_hgroup;
  HuffmanTreeGroup distance_hgroup;
  HuffmanCode* context_map_table;
  HuffmanCode scratch_table[1 << 15];  /* for temporary tables */

  const uint8_t* custom_dict;
  size_t custom_dict_size;
} State;

static void fail(State* s, int code) {
  s->error = code;
  longjmp(s->jb, 1);
}

/* ---------------- bit reader ---------------- */

static void refill_chunk(State* s) {
  if (s->eof) return;
  s->avail = s->io->read(s->io->opaque, &s->next);
  s->total_in += s->avail;
  if (s->avail == 0) s->eof = 1;
}

/* Fill accumulator with as many bytes as currently available (without pulling a new chunk
   unless the accumulator cannot satisfy `need` bits). Returns 1 if nbits >= need. */
static int fill_bits(State* s, uint32_t need) {
  for (;;) {
    while (s->nbits <= 56 && s->avail > 0) {
      s->acc |= (uint64_t)(*s->next) << s->nbits;
      s->next++;
      s->avail--;
      s->nbits += 8;
    }
    if (s->nbits >= need) return 1;
    if (s->eof) return 0;
    refill_chunk(s);
    if (s->avail == 0) return s->nbits >= need;
  }
}

static inline uint32_t read_bits(State* s, uint32_t n) {
  uint32_t v;
  if (n == 0) return 0;
  if (s->nbits < n) {
    if (!fill_bits(s, n)) fail(s, BR_DEC_NEEDS_MORE_INPUT);
  }
  v = (uint32_t)(s->acc & ((n == 32) ? 0xFFFFFFFFu : ((1u << n) - 1)));
  s->acc >>= n;
  s->nbits -= n;
  return v;
}

/* Peek up to 16 bits; missing bits (at EOF) are zero. */
static inline uint32_t peek_bits16(State* s) {
  if (s->nbits < 16) fill_bits(s, 16);
  return (uint32_t)(s->acc & 0xFFFF);
}
static inline void drop_bits(State* s, uint32_t n) {
  if (s->nbits < n) fail(s, BR_DEC_NEEDS_MORE_INPUT);
  s->acc >>= n;
  s->nbits -= n;
}

static void jump_to_byte_boundary(State* s, int err) {
  uint32_t pad = s->nbits & 7;
  if (pad) {
    uint32_t v = read_bits(s, pad);
    if (v != 0) fail(s, err);
  }
}

/* ---------------- Huffman ---------------- */

static inline uint32_t reverse_bits(uint32_t v, int len) {
  uint32_t r = 0;
  int i;
  for (i = 0; i < len; i++) { r = (r << 1) | (v & 1); v >>= 1; }
  return r;
}

/* Compute table size required for the code lengths. */
static size_t huffman_table_size(const uint8_t* lengths, uint32_t n) {
  uint32_t i;
  uint16_t count[16] = {0};
  uint32_t next_code[16];
  uint32_t code = 0;
  size_t size = 1u << HUFFMAN_ROOT_BITS;
  uint8_t maxlen_for_root[1 << HUFFMAN_ROOT_BITS];
  memset(maxlen_for_root, 0, sizeof(maxlen_for_root));
  for (i = 0; i < n; i++) if (lengths[i]) count[lengths[i]]++;
  for (i = 1; i < 16; i++) { next_code[i] = code; code = (code + count[i]) << 1; }
  for (i = 0; i < n; i++) {
    uint8_t l = lengths[i];
    if (l > HUFFMAN_ROOT_BITS) {
      uint32_t c = next_code[l]++;
      uint32_t rev = reverse_bits(c, l);
      uint32_t root = rev & ((1u << HUFFMAN_ROOT_BITS) - 1);
      if (l > maxlen_for_root[root]) maxlen_for_root[root] = l;
    } else if (l) {
      next_code[l]++;
    }
  }
  for (i = 0; i < (1u << HUFFMAN_ROOT_BITS); i++) {
    if (maxlen_for_root[i]) size += 1u << (maxlen_for_root[i] - HUFFMAN_ROOT_BITS);
  }
  return size;
}

/* Build table; returns number of entries used. `lengths` must describe a complete code. */
static size_t build_huffman_table(HuffmanCode* table, const uint8_t* lengths, uint32_t n) {
  uint32_t i;
  uint16_t count[16] = {0};
  uint32_t next_code[16];
  uint32_t code = 0;
  size_t size = 1u << HUFFMAN_ROOT_BITS;
  uint8_t maxlen_for_root[1 << HUFFMAN_ROOT_BITS];
  uint32_t sub_offset[1 << HUFFMAN_ROOT_BITS];
  uint32_t* codes = (uint32_t*)malloc(sizeof(uint32_t) * (n ? n : 1));
  memset(maxlen_for_root, 0, sizeof(maxlen_for_root));
  for (i = 0; i < n; i++) if (lengths[i]) count[lengths[i]]++;
  for (i = 1; i < 16; i++) { next_code[i] = code; code = (code + count[i]) << 1; }
  for (i = 0; i < n; i++) {
    uint8_t l = lengths[i];
    if (l) {
      uint32_t c = next_code[l]++;
      codes[i] = reverse_bits(c, l);
      if (l > HUFFMAN_ROOT_BITS) {
        uint32_t root = codes[i] & ((1u << HUFFMAN_ROOT_BITS) - 1);
        if (l > maxlen_for_root[root]) maxlen_for_root[root] = l;
      }
    }
  }
  for (i = 0; i < (1u << HUFFMAN_ROOT_BITS); i++) {
    if (maxlen_for_root[i]) {
      sub_offset[i] = (uint32_t)size;
      table[i].bits = (uint8_t)(16 + maxlen_for_root[i] - HUFFMAN_ROOT_BITS);
      table[i].value = (uint16_t)size;
      size += 1u << (maxlen_for_root[i] - HUFFMAN_ROOT_BITS);
    }
  }
  for (i = 0; i < n; i++) {
    uint8_t l = lengths[i];
    if (!l) continue;
    if (l <= HUFFMAN_ROOT_BITS) {
      uint32_t j;
      for (j = codes[i]; j < (1u << HUFFMAN_ROOT_BITS); j += 1u << l) {
        table[j].bits = l;
        table[j].value = (uint16_t)i;
      }
    } else {
      uint32_t root = codes[i] & ((1u << HUFFMAN_ROOT_BITS) - 1);
      uint32_t sub_bits = maxlen_for_root[root] - HUFFMAN_ROOT_BITS;
      HuffmanCode* sub = table + sub_offset[root];
      uint32_t hi = codes[i] >> HUFFMAN_ROOT_BITS;
      uint32_t j;
      for (j = hi; j < (1u << sub_bits); j += 1u << (l - HUFFMAN_ROOT_BITS)) {
        sub[j].bits = (uint8_t)(l - HUFFMAN_ROOT_BITS);
        sub[j].value = (uint16_t)i;
      }
    }
  }
  free(codes);
  return size;
}

static inline uint32_t read_symbol(State* s, const HuffmanCode* table) {
  uint32_t bits = peek_bits16(s);
  const HuffmanCode* e = &table[bits & ((1u << HUFFMAN_ROOT_BITS) - 1)];
  if (e->bits > 16) {
    uint32_t sub_bits = e->bits - 16;
    const HuffmanCode* sub = table + e->value;
    e = &sub[(bits >> HUFFMAN_ROOT_BITS) & ((1u << sub_bits) - 1)];
    drop_bits(s, HUFFMAN_ROOT_BITS + e->bits);
    return e->value;
  }
  drop_bits(s, e->bits);
  return e->value;
}

/* Code length code order and fixed code for code-length code lengths. */
static const uint8_t kCodeLengthCodeOrder[18] = {1, 2, 3, 4, 0, 5, 17, 6, 16, 7, 8, 9, 10, 11, 12, 13, 14, 15};
static const uint8_t kCodeLengthPrefixLength[16] = {2, 2, 2, 3, 2, 2, 2, 4, 2, 2, 2, 3, 2, 2, 2, 4};
static const uint8_t kCodeLengthPrefixValue[16] = {0, 4, 3, 2, 0, 4, 3, 1, 0, 4, 3, 2, 0, 4, 3, 5};

/* Reads a prefix code; writes table into `table` (must have enough room); returns table size. */
static size_t read_huffman_code(State* s, uint32_t alphabet_size_max, uint32_t alphabet_size_limit, HuffmanCode* table) {
  uint32_t simple_code_or_skip = read_bits(s, 2);
  if (simple_code_or_skip == 1) {
    /* simple code */
    uint32_t max_bits = 0;
    uint32_t x = alphabet_size_max - 1;
    uint32_t num_symbols = read_bits(s, 2);  /* NSYM - 1 */
    uint16_t val[4];
    uint32_t i, k;
    while (x) { x >>= 1; max_bits++; }
    for (i = 0; i <= num_symbols; i++) {
      uint32_t v = read_bits(s, max_bits);
      if (v >= alphabet_size_limit) fail(s, BR_DEC_ERR_FORMAT_SIMPLE_HUFFMAN_ALPHABET);
      val[i] = (uint16_t)v;
    }
    for (i = 0; i < num_symbols; i++) {
      for (k = i + 1; k <= num_symbols; k++) {
        if (val[i] == val[k]) fail(s, BR_DEC_ERR_FORMAT_SIMPLE_HUFFMAN_SAME);
      }
    }
    if (num_symbols == 3) {
      num_symbols += read_bits(s, 1);
    }
    switch (num_symbols) {
      case 0:
        table[0].bits = 0; table[0].value = val[0];
        return 1;
      case 1:
        if (val[1] > val[0]) { table[0].value = val[0]; table[1].value = val[1]; }
        else { table[0].value = val[1]; table[1].value = val[0]; }
        table[0].bits = 1; table[1].bits = 1;
        return 2;
      case 2:
        table[0].value = val[0]; table[2].value = val[0];
        if (val[2] > val[1]) { table[1].value = val[1]; table[3].value = val[2]; }
        else { table[1].value = val[2]; table[3].value = val[1]; }
        table[0].bits = 1; table[1].bits = 2; table[2].bits = 1; table[3].bits = 2;
        return 4;
      case 3: {
        for (i = 0; i < 3; i++) for (k = i + 1; k < 4; k++) if (val[k] < val[i]) { uint16_t t = val[k]; val[k] = val[i]; val[i] = t; }
        table[0].value = val[0]; table[2].value = val[1]; table[1].value = val[2]; table[3].value = val[3];
        table[0].bits = 2; table[1].bits = 2; table[2].bits = 2; table[3].bits = 2;
        return 4;
      }
      default: {
        if (val[3] < val[2]) { uint16_t t = val[3]; val[3] = val[2]; val[2] = t; }
        table[0].value = val[0]; table[1].value = val[1]; table[2].value = val[0]; table[3].value = val[2];
        table[4].value = val[0]; table[5].value = val[1]; table[6].value = val[0]; table[7].value = val[3];
        table[0].bits = 1; table[1].bits = 2; table[2].bits = 1; table[3].bits = 3;
        table[4].bits = 1; table[5].bits = 2; table[6].bits = 1; table[7].bits = 3;
        return 8;
      }
    }
  } else {
    /* complex code */
    uint8_t code_length_code_lengths[18];
    uint32_t space = 32;
    uint32_t num_codes = 0;
    uint32_t i;
    HuffmanCode cl_table[32];
    uint8_t* lengths;
    memset(code_length_code_lengths, 0, sizeof(code_length_code_lengths));
    for (i = simple_code_or_skip; i < 18; i++) {
      uint32_t bits = peek_bits16(s) & 15;
      uint32_t v = kCodeLengthPrefixValue[bits];
      drop_bits(s, kCodeLengthPrefixLength[bits]);
      code_length_code_lengths[kCodeLengthCodeOrder[i]] = (uint8_t)v;
      if (v != 0) {
        space -= (32u >> v);
        num_codes++;
        if ((int32_t)space <= 0) break;  /* space is unsigned; handle underflow like reference? */
      }
    }
    if (!(num_codes == 1 || space == 0)) fail(s, BR_DEC_ERR_FORMAT_CL_SPACE);
    /* build code length code table (5 bits max) */
    {
      uint32_t j;
      /* lengths are <= 5, so a flat 32-entry table */
      uint16_t count[6] = {0};
      uint32_t next_code[6];
      uint32_t code = 0;
      for (j = 0; j < 18; j++) if (code_length_code_lengths[j]) count[code_length_code_lengths[j]]++;
      for (j = 1; j < 6; j++) { next_code[j] = code; code = (code + count[j]) << 1; }
      if (num_codes == 1) {
        /* single symbol: zero-length code; find it */
        for (j = 0; j < 18; j++) if (code_length_code_lengths[j]) break;
        for (i = 0; i < 32; i++) { cl_table[i].bits = 0; cl_table[i].value = (uint16_t)j; }
      } else {
        for (i = 0; i < 32; i++) { cl_table[i].bits = 0; cl_table[i].value = 0; }
        for (j = 0; j < 18; j++) {
          uint8_t l = code_length_code_lengths[j];
          if (l) {
            uint32_t c = next_code[l]++;
            uint32_t rev = reverse_bits(c, l);
            uint32_t k;
            for (k = rev; k < 32; k += 1u << l) { cl_table[k].bits = l; cl_table[k].value = (uint16_t)j; }
          }
        }
      }
    }
    /* read symbol code lengths */
    lengths = (uint8_t*)calloc(alphabet_size_limit + 1, 1);
    {
      uint32_t symbol = 0;
      uint32_t repeat = 0;
      uint32_t prev_code_len = BR_INITIAL_REPEATED_CODE_LENGTH;
      uint32_t repeat_code_len = 0;
      space = 32768;
      while (symbol < alphabet_size_limit && space > 0) {
        uint32_t bits = peek_bits16(s) & 31;
        const HuffmanCode* p = &cl_table[bits];
        uint32_t code_len = p->value;
        drop_bits(s, p->bits);
        if (code_len < BR_REPEAT_PREVIOUS_CODE_LENGTH) {
          repeat = 0;
          if (code_len != 0) {
            lengths[symbol] = (uint8_t)code_len;
            prev_code_len = code_len;
            space -= 32768u >> code_len;
          }
          symbol++;
        } else {
          uint32_t extra_bits = (code_len == BR_REPEAT_PREVIOUS_CODE_LENGTH) ? 2 : 3;
          uint32_t new_len = (code_len == BR_REPEAT_PREVIOUS_CODE_LENGTH) ? prev_code_len : 0;
          uint32_t repeat_delta = read_bits(s, extra_bits);
          uint32_t old_repeat;
          if (repeat_code_len != new_len) {
            repeat = 0;
            repeat_code_len = new_len;
          }
          old_repeat = repeat;
          if (repeat > 0) {
            repeat -= 2;
            repeat <<= extra_bits;
          }
          repeat += repeat_delta + 3u;
          repeat_delta = repeat - old_repeat;
          if (symbol + repeat_delta > alphabet_size_limit) {
            symbol = alphabet_size_limit;
            space = 0xFFFFF;
            break;
          }
          if (repeat_code_len != 0) {
            uint32_t last = symbol + repeat_delta;
            while (symbol != last) lengths[symbol++] = (uint8_t)repeat_code_len;
            space -= repeat_delta << (15 - repeat_code_len);
          } else {
            symbol += repeat_delta;
          }
        }
      }
      if (space != 0) { free(lengths); fail(s, BR_DEC_ERR_FORMAT_HUFFMAN_SPACE); }
    }
    {
      size_t size = build_huffman_table(table, lengths, alphabet_size_limit);
      free(lengths);
      return size;
    }
  }
}

/* Reads a huffman code into scratch, then copies into a freshly allocated buffer. */
static HuffmanCode* read_huffman_code_alloc(State* s, uint32_t alphabet_size_max, uint32_t alphabet_size_limit) {
  size_t size = read_huffman_code(s, alphabet_size_max, alphabet_size_limit, s->scratch_table);
  HuffmanCode* t = (HuffmanCode*)malloc(sizeof(HuffmanCode) * size);
  memcpy(t, s->scratch_table, sizeof(HuffmanCode) * size);
  return t;
}

static void hgroup_init(HuffmanTreeGroup* g, uint32_t alphabet_size_max, uint32_t alphabet_size_limit, uint32_t num_htrees) {
  g->alphabet_size_max = alphabet_size_max;
  g->alphabet_size_limit = alphabet_size_limit;
  g->num_htrees = num_htrees;
  g->htrees = (HuffmanCode**)calloc(num_htrees, sizeof(HuffmanCode*));
  g->codes = NULL;
}
static void hgroup_free(HuffmanTreeGroup* g) {
  uint32_t i;
  if (g->htrees) {
    for (i = 0; i < g->num_htrees; i++) free(g->htrees[i]);
    free(g->htrees);
  }
  g->htrees = NULL;
  g->num_htrees = 0;
}
static void hgroup_decode(State* s, HuffmanTreeGroup* g) {
  uint32_t i;
  for (i = 0; i < g->num_htrees; i++) {
    g->htrees[i] = read_huffman_code_alloc(s, g->alphabet_size_max, g->alphabet_size_limit);
  }
}

/* ---------------- metablock header pieces ---------------- */

static uint32_t decode_var_len_uint8(State* s) {
  uint32_t bits = read_bits(s, 1);
  if (bits == 0) return 0;
  bits = read_bits(s, 3);
  if (bits == 0) return 1;
  {
    uint32_t extra = read_bits(s, bits);
    return (1u << bits) + extra;
  }
}

static void decode_metablock_length(State* s) {
  uint32_t bits;
  int i;
  s->is_last_metablock = (int)read_bits(s, 1);
  s->meta_block_remaining_len = 0;
  s->is_uncompressed = 0;
  s->is_metadata = 0;
  if (s->is_last_metablock) {
    bits = read_bits(s, 1);
    if (bits) return;  /* ISLASTEMPTY */
  }
  bits = read_bits(s, 2);
  if (bits == 3) {
    s->is_metadata = 1;
    bits = read_bits(s, 1);
    if (bits != 0) fail(s, BR_DEC_ERR_FORMAT_RESERVED);
    bits = read_bits(s, 2);
    if (bits == 0) return;
    {
      int nbytes = (int)bits;
      for (i = 0; i < nbytes; i++) {
        uint32_t b = read_bits(s, 8);
        if (i + 1 == nbytes && nbytes > 1 && b == 0) fail(s, BR_DEC_ERR_FORMAT_EXUBERANT_META_NIBBLE);
        s->meta_block_remaining_len |= (int)(b << (i * 8));
      }
    }
    s->meta_block_remaining_len++;
    return;
  }
  {
    int nibbles = (int)bits + 4;
    for (i = 0; i < nibbles; i++) {
      uint32_t b = read_bits(s, 4);
      if (i + 1 == nibbles && nibbles > 4 && b == 0) fail(s, BR_DEC_ERR_FORMAT_EXUBERANT_NIBBLE);
      s->meta_block_remaining_len |= (int)(b << (i * 4));
    }
  }
  if (!s->is_last_metablock) {
    s->is_uncompressed = (int)read_bits(s, 1);
  }
  s->meta_block_remaining_len++;
}

static void inverse_move_to_front_transform(uint8_t* v, uint32_t v_len) {
  uint8_t mtf[256];
  uint32_t i;
  for (i = 0; i < 256; i++) mtf[i] = (uint8_t)i;
  for (i = 0; i < v_len; i++) {
    uint8_t index = v[i];
    uint8_t value = mtf[index];
    uint32_t j;
    v[i] = value;
    for (j = index; j > 0; j--) mtf[j] = mtf[j - 1];
    mtf[0] = value;
  }
}

static uint8_t* decode_context_map(State* s, uint32_t context_map_size, uint32_t* num_htrees_out) {
  uint32_t num_htrees = decode_var_len_uint8(s) + 1;
  uint8_t* context_map = (uint8_t*)malloc(context_map_size);
  *num_htrees_out = num_htrees;
  if (num_htrees <= 1) {
    memset(context_map, 0, context_map_size);
    return context_map;
  }
  {
    uint32_t max_run_length_prefix = 0;
    uint32_t bits = read_bits(s, 1);
    uint32_t alphabet_size;
    HuffmanCode* table;
    uint32_t context_index = 0;
    if (bits != 0) {
      max_run_length_prefix = read_bits(s, 4) + 1;
    }
    alphabet_size = num_htrees + max_run_length_prefix;
    table = read_huffman_code_alloc(s, alphabet_size, alphabet_size);
    while (context_index < context_map_size) {
      uint32_t code = read_symbol(s, table);
      if (code == 0) { context_map[context_index++] = 0; continue; }
      if (code > max_run_length_prefix) { context_map[context_index++] = (uint8_t)(code - max_run_length_prefix); continue; }
      {
        uint32_t reps = read_bits(s, code);
        reps += 1u << code;
        if (context_index + reps > context_map_size) { free(table); fail(s, BR_DEC_ERR_FORMAT_CONTEXT_MAP_REPEAT); }
        do { context_map[context_index++] = 0; } while (--reps);
      }
    }
    free(table);
    bits = read_bits(s, 1);
    if (bits != 0) inverse_move_to_front_transform(context_map, context_map_size);
  }
  return context_map;
}

static uint32_t read_block_length(State* s, const HuffmanCode* table) {
  uint32_t code = read_symbol(s, table);
  uint32_t nbits = kBlockLengthPrefixCode[code].nbits;
  return kBlockLengthPrefixCode[code].offset + read_bits(s, nbits);
}

static void decode_block_type_and_length(State* s, int tree_type) {
  uint32_t max_block_type = s->num_block_types[tree_type];
  uint32_t* rb = &s->block_type_rb[tree_type * 2];
  uint32_t block_type = read_symbol(s, s->block_type_trees[tree_type]);
  s->block_length[tree_type] = read_block_length(s, s->block_len_trees[tree_type]);
  if (block_type == 1) block_type = rb[1] + 1;
  else if (block_type == 0) block_type = rb[0];
  else block_type -= 2;
  if (block_type >= max_block_type) block_type -= max_block_type;
  rb[0] = rb[1];
  rb[1] = block_type;
}

/* ---------------- ring buffer / output ---------------- */

static void calculate_ring_buffer_size(State* s) {
  int window_size = 1 << s->window_bits;
  int new_ringbuffer_size = window_size;
  int min_size = s->ringbuffer_size ? s->ringbuffer_size : 1024;
  int output_size;
  if (s->ringbuffer_size == window_size) return;
  if (s->is_metadata) return;
  if (!s->ringbuffer) output_size = 0; else output_size = s->pos;
  output_size += s->meta_block_remaining_len;
  min_size = min_size < output_size ? output_size : min_size;
  while ((new_ringbuffer_size >> 1) >= min_size) new_ringbuffer_size >>= 1;
  s->new_ringbuffer_size = new_ringbuffer_size;
}

static void ensure_ring_buffer(State* s) {
  uint8_t* old = s->ringbuffer;
  if (s->ringbuffer_size == s->new_ringbuffer_size) return;
  s->ringbuffer = (uint8_t*)malloc((size_t)s->new_ringbuffer_size + 42);
  if (!s->ringbuffer) { s->ringbuffer = old; fail(s, BR_DEC_ERR_ALLOC_RING_BUFFER_1); }
  s->ringbuffer[s->new_ringbuffer_size - 2] = 0;
  s->ringbuffer[s->new_ringbuffer_size - 1] = 0;
  if (old) {
    memcpy(s->ringbuffer, old, (size_t)s->pos);
    free(old);
  }
  s->ringbuffer_size = s->new_ringbuffer_size;
  s->ringbuffer_mask = s->new_ringbuffer_size - 1;
}

/* Emit all unwritten bytes of the ring buffer; handles wrap. */
static void write_ring_buffer(State* s) {
  size_t pos = (size_t)s->pos + ((size_t)s->rb_roundtrips << s->window_bits);
  size_t partial = s->partial_pos_out;
  size_t to_write;
  if (s->meta_block_remaining_len < 0) fail(s, BR_DEC_ERR_FORMAT_BLOCK_LENGTH_1);
  /* The ring buffer size may be less than the window (before reaching full size); compute pos
     accordingly: roundtrips only happen with full-size buffer. */
  to_write = pos - partial;
  if (to_write > 0) {
    const uint8_t* start = s->ringbuffer + (partial & (size_t)s->ringbuffer_mask);
    if (!s->io->write(s->io->opaque, start, to_write)) fail(s, BR_DEC_ABORT_OUTPUT);
    s->partial_pos_out += to_write;
  }
  if (s->ringbuffer_size == (1 << s->window_bits) && s->pos >= s->ringbuffer_size) {
    s->pos -= s->ringbuffer_size;
    s->rb_roundtrips++;
  }
}

static void after_write(State* s) {
  if (s->ringbuffer_size == 1 << s->window_bits) s->max_distance = s->max_backward_distance;
}

/* ---------------- uncompressed block ---------------- */

static void copy_uncompressed_block(State* s) {
  ensure_ring_buffer(s);
  for (;;) {
    int nbytes;
    /* first, whole bytes from accumulator */
    while (s->meta_block_remaining_len > 0 && s->nbits >= 8 && s->pos < s->ringbuffer_size) {
      s->ringbuffer[s->pos++] = (uint8_t)(s->acc & 0xFF);
      s->acc >>= 8;
      s->nbits -= 8;
      s->meta_block_remaining_len--;
    }
    if (s->meta_block_remaining_len > 0 && s->pos < s->ringbuffer_size) {
      if (s->avail == 0) {
        refill_chunk(s);
        if (s->avail == 0) fail(s, BR_DEC_NEEDS_MORE_INPUT);
      }
      nbytes = (int)BR_MIN(s->avail, (size_t)s->meta_block_remaining_len);
      if (s->pos + nbytes > s->ringbuffer_size) nbytes = s->ringbuffer_size - s->pos;
      memcpy(&s->ringbuffer[s->pos], s->next, (size_t)nbytes);
      s->next += nbytes;
      s->avail -= (size_t)nbytes;
      s->pos += nbytes;
      s->meta_block_remaining_len -= nbytes;
    }
    if (s->pos < (1 << s->window_bits)) {
      if (s->meta_block_remaining_len == 0) return;
      continue;
    }
    write_ring_buffer(s);
    after_write(s);
    if (s->meta_block_remaining_len == 0) return;
  }
}

/* ---------------- distance ---------------- */

static void take_distance_from_ring_buffer(State* s, int* distance_code, int* dist_rb_idx_adjust) {
  int code = *distance_code;
  if (code <= 3) {
    int offset = code - 3;
    *dist_rb_idx_adjust = 1 >> code; /* 1 for code 0, else 0 */
    *distance_code = s->dist_rb[(s->dist_rb_idx - offset) & 3];
    s->dist_rb_idx -= *dist_rb_idx_adjust;
  } else {
    int index_delta = 3;
    int delta;
    int base = code - 10;
    *dist_rb_idx_adjust = 0;
    if (code < 10) base = code - 4; else index_delta = 2;
    delta = ((0x605142 >> (4 * base)) & 0xF) - 3;
    *distance_code = s->dist_rb[(s->dist_rb_idx + index_delta) & 3] + delta;
    if (*distance_code <= 0) *distance_code = 0x7FFFFFFF;
  }
}

typedef struct {
  uint32_t max_alphabet_size;
  uint32_t max_distance;
} DistanceCodeLimit;

static DistanceCodeLimit calculate_distance_code_limit(uint32_t max_distance, uint32_t npostfix, uint32_t ndirect) {
  DistanceCodeLimit r;
  uint32_t dcode;
  uint32_t count = 0;
  uint32_t last_max = 0;
  if (max_distance <= ndirect) {
    r.max_alphabet_size = max_distance + BR_NUM_DISTANCE_SHORT_CODES;
    r.max_distance = max_distance;
    return r;
  }
  for (dcode = 0;; dcode++) {
    uint32_t hcode = dcode >> npostfix;
    uint32_t lcode = dcode & ((1u << npostfix) - 1);
    uint32_t ndistbits = 1 + (dcode >> (npostfix + 1));
    uint64_t offset = (((uint64_t)2 + (hcode & 1)) << ndistbits) - 4;
    uint64_t min_d = (offset << npostfix) + lcode + ndirect + 1;
    uint64_t max_d = ((offset + ((1ull << ndistbits) - 1)) << npostfix) + lcode + ndirect + 1;
    if (min_d > max_distance) break;
    count++;
    last_max = (uint32_t)BR_MIN(max_d, (uint64_t)max_distance);
    if (ndistbits > 40) break;
  }
  r.max_alphabet_size = BR_NUM_DISTANCE_SHORT_CODES + ndirect + count;
  r.max_distance = last_max;
  return r;
}

/* ---------------- main ---------------- */

static void free_metablock(State* s) {
  int i;
  for (i = 0; i < 3; i++) {
    free(s->block_type_trees[i]); s->block_type_trees[i] = NULL;
    free(s->block_len_trees[i]); s->block_len_trees[i] = NULL;
  }
  free(s->context_modes); s->context_modes = NULL;
  free(s->context_map); s->context_map = NULL;
  free(s->dist_context_map); s->dist_context_map = NULL;
  hgroup_free(&s->literal_hgroup);
  hgroup_free(&s->insert_copy_hgroup);
  hgroup_free(&s->distance_hgroup);
}

static void decode_window_bits(State* s) {
  uint32_t n = read_bits(s, 1);
  s->large_window = 0;
  if (n == 0) { s->window_bits = 16; return; }
  n = read_bits(s, 3);
  if (n != 0) { s->window_bits = 17 + (int)n; return; }
  n = read_bits(s, 3);
  if (n == 1) {
    /* large window */
    n = read_bits(s, 1);
    if (n == 1) fail(s, BR_DEC_ERR_FORMAT_WINDOW_BITS);
    s->large_window = 1;
    n = read_bits(s, 6);
    if (n < 10 || n > 30) fail(s, BR_DEC_ERR_FORMAT_WINDOW_BITS);
    s->window_bits = (int)n;
    return;
  }
  if (n != 0) { s->window_bits = 8 + (int)n; return; }
  s->window_bits = 17;
}

static void process_metablock_body(State* s) {
  int i;
  int pos = s->pos;
  /* Header: block types */
  for (i = 0; i < 3; i++) {
    s->num_block_types[i] = decode_var_len_uint8(s) + 1;
    if (s->num_block_types[i] >= 2) {
      uint32_t alphabet_size = s->num_block_types[i] + 2;
      s->block_type_trees[i] = read_huffman_code_alloc(s, alphabet_size, alphabet_size);
      s->block_len_trees[i] = read_huffman_code_alloc(s, BR_NUM_BLOCK_LEN_SYMBOLS, BR_NUM_BLOCK_LEN_SYMBOLS);
      s->block_length[i] = read_block_length(s, s->block_len_trees[i]);
    } else {
      s->block_length[i] = 1u << 24;
    }
  }
  {
    uint32_t bits = read_bits(s, 6);
    s->distance_postfix_bits = bits & 3;
    bits >>= 2;
    s->num_direct_distance_codes = bits << s->distance_postfix_bits;
    s->distance_postfix_mask = (1u << s->distance_postfix_bits) - 1;
  }
  s->context_modes = (uint8_t*)malloc(s->num_block_types[0]);
  for (i = 0; i < (int)s->num_block_types[0]; i++) {
    s->context_modes[i] = (uint8_t)read_bits(s, 2);
  }
  s->context_map = decode_context_map(s, s->num_block_types[0] << BR_LITERAL_CONTEXT_BITS, &s->num_literal_htrees);
  {
    uint32_t npostfix = s->distance_postfix_bits;
    uint32_t ndirect = s->num_direct_distance_codes;
    uint32_t dist_max = BR_DISTANCE_ALPHABET_SIZE(npostfix, ndirect, BR_MAX_DISTANCE_BITS);
    uint32_t dist_limit = dist_max;
    if (s->large_window) {
      DistanceCodeLimit limit = calculate_distance_code_limit(BR_MAX_ALLOWED_DISTANCE, npostfix, ndirect);
      dist_max = BR_DISTANCE_ALPHABET_SIZE(npostfix, ndirect, BR_LARGE_MAX_DISTANCE_BITS);
      dist_limit = limit.max_alphabet_size;
    }
    s->dist_context_map = decode_context_map(s, s->num_block_types[2] << BR_DISTANCE_CONTEXT_BITS, &s->num_dist_htrees);
    hgroup_init(&s->literal_hgroup, BR_NUM_LITERAL_SYMBOLS, BR_NUM_LITERAL_SYMBOLS, s->num_literal_htrees);
    hgroup_init(&s->insert_copy_hgroup, BR_NUM_COMMAND_SYMBOLS, BR_NUM_COMMAND_SYMBOLS, s->num_block_types[1]);
    hgroup_init(&s->distance_hgroup, dist_max, dist_limit, s->num_dist_htrees);
  }
  hgroup_decode(s, &s->literal_hgroup);
  hgroup_decode(s, &s->insert_copy_hgroup);
  hgroup_decode(s, &s->distance_hgroup);

  ensure_ring_buffer(s);

  /* Command loop */
  {
    uint32_t literal_block_type = 0;
    uint32_t command_block_type = 0;
    uint32_t distance_block_type = 0;
    const uint8_t* context_map_slice = s->context_map;
    const uint8_t* dist_context_map_slice = s->dist_context_map;
    int context_mode = s->context_modes[0];
    const HuffmanCode* htree_command = s->insert_copy_hgroup.htrees[0];
    s->block_type_rb[0] = 1; s->block_type_rb[1] = 0;
    s->block_type_rb[2] = 1; s->block_type_rb[3] = 0;
    s->block_type_rb[4] = 1; s->block_type_rb[5] = 0;

    for (;;) {
      uint32_t cmd_code;
      int insert_length;
      int copy_length;
      int distance_code; /* -1: explicit */
      int distance_context;
      /* command block switch */
      if (s->block_length[1] == 0) {
        decode_block_type_and_length(s, 1);
        command_block_type = s->block_type_rb[3];
        htree_command = s->insert_copy_hgroup.htrees[command_block_type];
      }
      cmd_code = read_symbol(s, htree_command);
      {
        const CmdLutElement* v = &kCmdLut[cmd_code];
        distance_code = v->distance_code;
        distance_context = v->context;
        insert_length = v->insert_len_offset;
        if (v->insert_len_extra_bits) insert_length += (int)read_bits(s, v->insert_len_extra_bits);
        copy_length = v->copy_len_offset + (int)read_bits(s, v->copy_len_extra_bits);
      }
      s->block_length[1]--;
      pos = s->pos;
      if (insert_length > 0) {
        s->meta_block_remaining_len -= insert_length;
        i = insert_length;
        while (i > 0) {
          uint8_t p1, p2, ctx;
          const HuffmanCode* lit_tree;
          if (s->block_length[0] == 0) {
            decode_block_type_and_length(s, 0);
            literal_block_type = s->block_type_rb[1];
            context_map_slice = s->context_map + (literal_block_type << BR_LITERAL_CONTEXT_BITS);
            context_mode = s->context_modes[literal_block_type];
          }
          p1 = s->ringbuffer[(pos - 1) & s->ringbuffer_mask];
          p2 = s->ringbuffer[(pos - 2) & s->ringbuffer_mask];
          ctx = br_context(p1, p2, context_mode);
          lit_tree = s->literal_hgroup.htrees[context_map_slice[ctx]];
          s->ringbuffer[pos] = (uint8_t)read_symbol(s, lit_tree);
          s->block_length[0]--;
          pos++;
          i--;
          if (pos == s->ringbuffer_size) {
            s->pos = pos;
            write_ring_buffer(s);
            after_write(s);
            pos = s->pos;
          }
        }
        s->pos = pos;
        if (s->meta_block_remaining_len <= 0) return;
      }
      /* distance */
      {
        int dist_rb_idx_adjust = 0;
        if (distance_code >= 0) {
          /* implicit: last distance */
          dist_rb_idx_adjust = 1;
          s->dist_rb_idx--;
          distance_code = s->dist_rb[s->dist_rb_idx & 3];
        } else {
          uint32_t code;
          if (s->block_length[2] == 0) {
            decode_block_type_and_length(s, 2);
            distance_block_type = s->block_type_rb[5];
            dist_context_map_slice = s->dist_context_map + (distance_block_type << BR_DISTANCE_CONTEXT_BITS);
          }
          code = read_symbol(s, s->distance_hgroup.htrees[dist_context_map_slice[distance_context]]);
          s->block_length[2]--;
          if ((code & ~0xFu) == 0) {
            distance_code = (int)code;
            take_distance_from_ring_buffer(s, &distance_code, &dist_rb_idx_adjust);
          } else {
            int distval = (int)code - BR_NUM_DISTANCE_SHORT_CODES - (int)s->num_direct_distance_codes;
            if (distval >= 0) {
              uint32_t nbits;
              int postfix = distval & (int)s->distance_postfix_mask;
              int64_t offset;
              uint32_t bits;
              distval >>= s->distance_postfix_bits;
              nbits = ((uint32_t)distval >> 1) + 1;
              bits = read_bits(s, nbits);
              offset = (((int64_t)2 + (distval & 1)) << nbits) - 4;
              {
                int64_t d = (int64_t)s->num_direct_distance_codes + ((offset + (int64_t)bits) << s->distance_postfix_bits) + postfix + 1;
                if (d > 0x7FFFFFFF) d = 0x7FFFFFFF;
                distance_code = (int)d;
              }
            } else {
              distance_code = (int)code - BR_NUM_DISTANCE_SHORT_CODES + 1;
            }
          }
        }
        /* max distance */
        if (s->max_distance != s->max_backward_distance) {
          s->max_distance = (pos < s->max_backward_distance) ? pos : s->max_backward_distance;
        }
        i = copy_length;
        if (distance_code > s->max_distance) {
          if (distance_code > BR_MAX_ALLOWED_DISTANCE) fail(s, BR_DEC_ERR_FORMAT_DISTANCE);
          {
            int address = distance_code - s->max_distance - 1;
            if (s->custom_dict && (size_t)address < s->custom_dict_size) {
              /* compound dictionary copy */
              size_t start = s->custom_dict_size - (size_t)address - 1;
              if (start + (size_t)i > s->custom_dict_size) fail(s, BR_DEC_ERR_COMPOUND_DICTIONARY);
              s->dist_rb[s->dist_rb_idx & 3] = distance_code;
              s->dist_rb_idx++;
              s->meta_block_remaining_len -= i;
              {
                const uint8_t* src = s->custom_dict + start;
                while (i > 0) {
                  int space = s->ringbuffer_size - pos;
                  int n = i < space ? i : space;
                  memcpy(&s->ringbuffer[pos], src, (size_t)n);
                  src += n; pos += n; i -= n;
                  if (pos == s->ringbuffer_size) {
                    s->pos = pos;
                    write_ring_buffer(s);
                    after_write(s);
                    pos = s->pos;
                  }
                }
              }
              s->pos = pos;
              if (s->meta_block_remaining_len <= 0) return;
              continue;
            }
            if (s->custom_dict) address -= (int)s->custom_dict_size;
            if (i >= BR_MIN_DICTIONARY_WORD_LENGTH && i <= BR_MAX_DICTIONARY_WORD_LENGTH) {
              int offset = (int)kBrotliDictionaryOffsetsByLength[i];
              uint32_t shift = kBrotliDictionarySizeBitsByLength[i];
              int mask = (int)((1u << shift) - 1);
              int word_idx = address & mask;
              int transform_idx = address >> shift;
              /* Compensate double distance-ring-buffer roll. */
              s->dist_rb_idx += dist_rb_idx_adjust;
              offset += word_idx * i;
              if (transform_idx < BR_NUM_TRANSFORMS) {
                const uint8_t* word = &kBrotliDictionaryData[offset];
                int len = i;
                uint8_t tmp[64];
                if (transform_idx == 0) {
                  memcpy(tmp, word, (size_t)len);
                } else {
                  len = br_transform_dictionary_word(tmp, word, len, transform_idx);
                }
                s->meta_block_remaining_len -= len;
                {
                  const uint8_t* src = tmp;
                  while (len > 0) {
                    int space = s->ringbuffer_size - pos;
                    int n = len < space ? len : space;
                    memcpy(&s->ringbuffer[pos], src, (size_t)n);
                    src += n; pos += n; len -= n;
                    if (pos >= s->ringbuffer_size) {
                      s->pos = pos;
                      write_ring_buffer(s);
                      after_write(s);
                      pos = s->pos;
                    }
                  }
                }
                s->pos = pos;
              } else {
                fail(s, BR_DEC_ERR_FORMAT_TRANSFORM);
              }
            } else {
              fail(s, BR_DEC_ERR_FORMAT_DICTIONARY);
            }
          }
        } else {
          /* LZ77 copy */
          s->dist_rb[s->dist_rb_idx & 3] = distance_code;
          s->dist_rb_idx++;
          s->meta_block_remaining_len -= i;
          while (i > 0) {
            s->ringbuffer[pos] = s->ringbuffer[(pos - distance_code) & s->ringbuffer_mask];
            pos++;
            i--;
            if (pos == s->ringbuffer_size) {
              s->pos = pos;
              write_ring_buffer(s);
              after_write(s);
              pos = s->pos;
            }
          }
          s->pos = pos;
        }
        if (s->meta_block_remaining_len <= 0) return;
      }
    }
  }
}

static void decode_main(State* s) {
  /* window bits */
  if (!fill_bits(s, 1)) fail(s, BR_DEC_NEEDS_MORE_INPUT);
  decode_window_bits(s);
  s->max_backward_distance = (1 << s->window_bits) - BR_WINDOW_GAP;
  s->dist_rb[0] = 16; s->dist_rb[1] = 15; s->dist_rb[2] = 11; s->dist_rb[3] = 4;
  s->dist_rb_idx = 0;
  for (;;) {
    /* metablock begin */
    s->block_length[0] = s->block_length[1] = s->block_length[2] = 1u << 24;
    s->num_block_types[0] = s->num_block_types[1] = s->num_block_types[2] = 1;
    decode_metablock_length(s);
    if (s->is_metadata || s->is_uncompressed) {
      jump_to_byte_boundary(s, BR_DEC_ERR_FORMAT_PADDING_1);
    }
    if (s->is_metadata) {
      size_t size = (size_t)s->meta_block_remaining_len;
      if (s->io->meta_start && !s->io->meta_start(s->io->opaque, size)) fail(s, BR_DEC_ABORT_METADATA);
      while (s->meta_block_remaining_len > 0) {
        uint8_t b = (uint8_t)read_bits(s, 8);
        if (s->io->meta_chunk && !s->io->meta_chunk(s->io->opaque, &b, 1)) fail(s, BR_DEC_ABORT_METADATA);
        s->meta_block_remaining_len--;
      }
      if (s->io->meta_end && !s->io->meta_end(s->io->opaque)) fail(s, BR_DEC_ABORT_METADATA);
    } else if (s->meta_block_remaining_len == 0) {
      /* empty (last) block */
    } else {
      calculate_ring_buffer_size(s);
      if (s->is_uncompressed) {
        copy_uncompressed_block(s);
      } else {
        process_metablock_body(s);
        free_metablock(s);
      }
    }
    /* metablock done */
    if (s->meta_block_remaining_len < 0) fail(s, BR_DEC_ERR_FORMAT_BLOCK_LENGTH_2);
    if (!s->is_last_metablock) continue;
    jump_to_byte_boundary(s, BR_DEC_ERR_FORMAT_PADDING_2);
    break;
  }
  /* done: write remaining */
  if (s->ringbuffer) {
    write_ring_buffer(s);
  }
}

void br_decode_stream(const BrDecoderIO* io, BrDecoderStatus* status) {
  State* s = (State*)calloc(1, sizeof(State));
  s->io = io;
  s->custom_dict = io->custom_dict;
  s->custom_dict_size = io->custom_dict_size;
  if (setjmp(s->jb) == 0) {
    decode_main(s);
    status->result = BR_DEC_SUCCESS;
  } else {
    status->result = s->error;
  }
  status->rest = s->next - (s->nbits >> 3);
  status->rest_len = s->avail + (s->nbits >> 3);
  status->total_in = s->total_in;
  free_metablock(s);
  free(s->ringbuffer);
  free(s);
}

const char* br_decoder_error_string(int code) {
  switch (code) {
    case BR_DEC_ERR_FORMAT_EXUBERANT_NIBBLE: return "FORMAT_EXUBERANT_NIBBLE";
    case BR_DEC_ERR_FORMAT_RESERVED: return "FORMAT_RESERVED";
    case BR_DEC_ERR_FORMAT_EXUBERANT_META_NIBBLE: return "FORMAT_EXUBERANT_META_NIBBLE";
    case BR_DEC_ERR_FORMAT_SIMPLE_HUFFMAN_ALPHABET: return "FORMAT_SIMPLE_HUFFMAN_ALPHABET";
    case BR_DEC_ERR_FORMAT_SIMPLE_HUFFMAN_SAME: return "FORMAT_SIMPLE_HUFFMAN_SAME";
    case BR_DEC_ERR_FORMAT_CL_SPACE: return "FORMAT_CL_SPACE";
    case BR_DEC_ERR_FORMAT_HUFFMAN_SPACE: return "FORMAT_HUFFMAN_SPACE";
    case BR_DEC_ERR_FORMAT_CONTEXT_MAP_REPEAT: return "FORMAT_CONTEXT_MAP_REPEAT";
    case BR_DEC_ERR_FORMAT_BLOCK_LENGTH_1: return "FORMAT_BLOCK_LENGTH_1";
    case BR_DEC_ERR_FORMAT_BLOCK_LENGTH_2: return "FORMAT_BLOCK_LENGTH_2";
    case BR_DEC_ERR_FORMAT_TRANSFORM: return "FORMAT_TRANSFORM";
    case BR_DEC_ERR_FORMAT_DICTIONARY: return "FORMAT_DICTIONARY";
    case BR_DEC_ERR_FORMAT_WINDOW_BITS: return "FORMAT_WINDOW_BITS";
    case BR_DEC_ERR_FORMAT_PADDING_1: return "FORMAT_PADDING_1";
    case BR_DEC_ERR_FORMAT_PADDING_2: return "FORMAT_PADDING_2";
    case BR_DEC_ERR_FORMAT_DISTANCE: return "FORMAT_DISTANCE";
    case BR_DEC_ERR_COMPOUND_DICTIONARY: return "COMPOUND_DICTIONARY";
    case BR_DEC_ERR_DICTIONARY_NOT_SET: return "DICTIONARY_NOT_SET";
    case BR_DEC_ERR_INVALID_ARGUMENTS: return "INVALID_ARGUMENTS";
    case BR_DEC_ERR_ALLOC_CONTEXT_MODES: return "ALLOC_CONTEXT_MODES";
    case BR_DEC_ERR_ALLOC_TREE_GROUPS: return "ALLOC_TREE_GROUPS";
    case BR_DEC_ERR_ALLOC_CONTEXT_MAP: return "ALLOC_CONTEXT_MAP";
    case BR_DEC_ERR_ALLOC_RING_BUFFER_1: return "ALLOC_RING_BUFFER_1";
    case BR_DEC_ERR_ALLOC_RING_BUFFER_2: return "ALLOC_RING_BUFFER_2";
    case BR_DEC_ERR_ALLOC_BLOCK_TYPE_TREES: return "ALLOC_BLOCK_TYPE_TREES";
    case BR_DEC_ERR_UNREACHABLE: return "UNREACHABLE";
    default: return "INVALID";
  }
}
