    int n = 2 + rand() % 703;
    uint8_t lengths[704]; memset(lengths, 0, sizeof lengths);
    /* build random huffman tree: start with symbols at depth 0, split leaves */
    /* simple: random code lengths via kraft: pick k symbols, assign lengths by repeatedly splitting */
    int k = 1 + rand() % (n < 300 ? n : 300);
    if (k == 1) continue;
    /* lengths via splitting: start with one leaf of length 0 */
    int len_of[704]; int cnt = 1; len_of[0] = 0;
    while (cnt < k) { int i = rand() % cnt; if (len_of[i] >= 15) continue; len_of[cnt++] = len_of[i] + 1; len_of[i]++; }
    /* assign to random distinct symbols */
    int perm[704]; for (int i = 0; i < n; i++) perm[i] = i;
    for (int i = n - 1; i > 0; i--) { int j = rand() % (i + 1); int t = perm[i]; perm[i] = perm[j]; perm[j] = t; }
    for (int i = 0; i < k; i++) lengths[perm[i]] = (uint8_t)len_of[i];
    HuffmanCode* table = malloc(sizeof(HuffmanCode) * 70000);
    size_t size = build_huffman_table(table, lengths, n);
    size_t expect = huffman_table_size(lengths, n);
    if (size != expect) { printf("size mismatch %zu %zu\n", size, expect); return 1; }
    /* canonical codes */
    uint16_t count[16] = {0}; uint32_t next_code[16]; uint32_t code = 0;
    for (int i = 0; i < n; i++) if (lengths[i]) count[lengths[i]]++;
    for (int i = 1; i < 16; i++) { next_code[i] = code; code = (code + count[i]) << 1; }
    for (int i = 0; i < n; i++) {
      if (!lengths[i]) continue;
      uint32_t c = next_code[lengths[i]]++;
      uint32_t rev = reverse_bits(c, lengths[i]);
      /* decode using table with random extra bits */
      uint32_t bits = rev | ((uint32_t)rand() << lengths[i]);
      const HuffmanCode* e = &table[bits & 255];
      uint32_t sym, len;
      if (e->bits > 16) { const HuffmanCode* sub = table + e->value; uint32_t sb = e->bits - 16; e = &sub[(bits >> 8) & ((1u << sb) - 1)]; sym = e->value; len = 8 + e->bits; }
      else { sym = e->value; len = e->bits; }
      if (sym != (uint32_t)i || len != lengths[i]) { printf("decode mismatch trial %d sym %d len %d got %u len %u\n", trial, i, lengths[i], sym, len); return 1; }
    }
    free(table);
  }
  printf("huffman ok\n");
  return 0;
}
