#define DEFAULT_LGWIN 24
#define DEFAULT_SUFFIX ".br"
#define MAX_OPTIONS 24
#define MAX_COMMENT_LEN 80

typedef enum {
  COMMAND_COMPRESS,
  COMMAND_DECOMPRESS,
  COMMAND_HELP,
  COMMAND_INVALID,
  COMMAND_TEST_INTEGRITY,
  COMMAND_NOOP,
  COMMAND_VERSION
} Command;

typedef struct {
  /* Parameters */
  int quality;
  int lgwin;
  int verbosity;
  int force_overwrite;
  int junk_source;
  int reject_uncompressible;
  int copy_stat;
  int write_to_stdout;
  int test_integrity;
  int decompress;
  int large_window;
  int allow_concatenated;
  const char* output_path;
  const char* dictionary_path;
  const char* suffix;
  uint8_t comment[MAX_COMMENT_LEN];
  size_t comment_len;
  int not_input_indices[MAX_OPTIONS];
  size_t longest_path_len;
  size_t input_count;

  /* Inner state */
  int argc;
  char** argv;
  uint8_t* dictionary;
  size_t dictionary_size;
  BrPreparedDictionary* prepared_dictionary;
  char* modified_path;
  int iterator;
  int ignore;
  int iterator_error;
  uint8_t* buffer;
  uint8_t* input;
  uint8_t* output;
  const char* current_input_path;
  const char* current_output_path;
  int64_t input_file_length;
  FILE* fin;
  FILE* fout;

  /* I/O buffers */
  size_t available_in;
  const uint8_t* next_in;
  size_t available_out;
  uint8_t* next_out;

  /* Reporting */
  size_t total_in;
  size_t total_out;
  clock_t start_time;
  clock_t end_time;

  /* decoder helpers */
  int read_error;
  int write_error;
  int comment_state;   /* 0: not seen, 1: checking first metadata, 2: done (ok), -1: mismatch */
  size_t comment_pos;
  int decoder_eof;
} Context;

static const size_t kFileBufferSize = 1 << 19;

static void PrintVersion(void) {
  fprintf(stdout, "brotli %d.%d.%d\n", 1, 2, 0);
}

static void PrintHelp(const char* name, int error) {
  /* Observed: help on success goes to stderr, on error to stdout. */
  FILE* media = error ? stdout : stderr;
  fprintf(media,
"Usage: %s [OPTION]... [FILE]...\n",
          name);
  fprintf(media,
"Options:\n"
"  -#                          compression level (0-9)\n"
"  -c, --stdout                write on standard output\n"
"  -d, --decompress            decompress\n"
"  -f, --force                 force output file overwrite\n"
"  -h, --help                  display this help and exit\n"
"  -j, --rm                    remove source file(s)\n"
"  -s, --squash                remove destination file if larger than source\n"
"  -k, --keep                  keep source file(s) (default)\n"
"  -n, --no-copy-stat          do not copy source file(s) attributes\n"
"  -o FILE, --output=FILE      output file (only if 1 input file)\n");
  fprintf(media,
"  -q NUM, --quality=NUM       compression level (0-11)\n"
"  -t, --test                  test compressed file integrity\n"
"  -v, --verbose               verbose mode\n"
"  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)\n"
"                              window size = 2**NUM - 16\n"
"                              0 lets compressor choose the optimal value\n"
"  --large_window=NUM          use incompatible large-window brotli\n"
"                              bitstream with window size (0, 10-30)\n"
"                              WARNING: this format is not compatible\n"
"                              with brotli RFC 7932 and may not be\n"
"                              decodable with regular brotli decoders\n");
  fprintf(media,
"  -C B64, --comment=B64       set comment; argument is base64-decoded first;\n"
"                              (maximal decoded length: 80)\n"
"                              when decoding: check stream comment;\n"
"                              when encoding: embed comment (fingerprint)\n"
"  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary\n"
"  -K, --concatenated          allows concatenated brotli streams as input\n"
"  -S SUF, --suffix=SUF        output file suffix (default:'%s')\n",
          DEFAULT_SUFFIX);
  fprintf(media,
"  -V, --version               display version and exit\n"
"  -Z, --best                  use best compression level (11) (default)\n"
"Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.\n"
"With no FILE, or when FILE is -, read standard input.\n"
"All arguments after '--' are treated as files.\n");
}

static const char* FileName(const char* path) {
  const char* separator_position = strrchr(path, '/');
  if (separator_position) path = separator_position + 1;
  separator_position = strrchr(path, '\\');
  if (separator_position) path = separator_position + 1;
  return path;
}

static const char* PrintablePath(const char* path) {
  return path ? path : "con";
}

static int ParseInt(const char* s, int low, int high, int* result) {
  int value = 0;
  int i;
  for (i = 0; i < 5; ++i) {
    char c = s[i];
    if (c == 0) break;
    if (s[i] >= '0' && s[i] <= '9') {
      value = (10 * value) + (c - '0');
    } else {
      return 0;
    }
  }
  if (i == 0) return 0;
  if (i > 1 && s[0] == '0') return 0;
  if (s[i] != 0) return 0;
  if (value < low || value > high) return 0;
  *result = value;
  return 1;
}

static int ParseBase64(const char* s, uint8_t* out, size_t* out_len) {
  uint32_t acc = 0;
  int bits = 0;
  int pad = 0;
  size_t len = 0;
  for (; *s; ++s) {
    char c = *s;
    int v;
    if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
    if (c == '=') {
      pad++;
      if (pad > 2) return 0;
      continue;
    }
    if (pad > 0) return 0;
    if (c >= 'A' && c <= 'Z') v = c - 'A';
    else if (c >= 'a' && c <= 'z') v = c - 'a' + 26;
    else if (c >= '0' && c <= '9') v = c - '0' + 52;
    else if (c == '+' || c == '-') v = 62;
    else if (c == '/' || c == '_') v = 63;
    else return 0;
    acc = (acc << 6) | (uint32_t)v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      if (len >= MAX_COMMENT_LEN) return 0;
      out[len++] = (uint8_t)((acc >> bits) & 0xFF);
    }
  }
  *out_len = len;
  return 1;
}

/* Detect special program name aliases. */
static Command ParseAlias(const char* name, Context* params) {
  const char* unbrotli = "unbrotli";
  const char* brcat = "brcat";
  size_t unbrotli_len = strlen(unbrotli);
  size_t brcat_len = strlen(brcat);
  name = FileName(name);
  if (strncmp(name, unbrotli, unbrotli_len) == 0) {
    char terminator = name[unbrotli_len];
    if (terminator == 0 || terminator == '.') return COMMAND_DECOMPRESS;
  }
  if (strncmp(name, brcat, brcat_len) == 0) {
    char terminator = name[brcat_len];
    if (terminator == 0 || terminator == '.') {
      params->write_to_stdout = 1;
      params->allow_concatenated = 1;
      return COMMAND_DECOMPRESS;
    }
  }
  return COMMAND_COMPRESS;
}

static Command ParseParams(Context* params) {
  int argc = params->argc;
  char** argv = params->argv;
  int i;
  int next_option_index = 0;
  size_t input_count = 0;
  int command_set = 0;
  int quality_set = 0;
  int output_set = 0;
  int keep_set = 0;
  int lgwin_set = 0;
  int suffix_set = 0;
  int comment_set = 0;
  int after_dash_dash = 0;
  Command command = ParseAlias(argv[0], params);
  int alias_stdout = params->write_to_stdout;
  int alias_concat = params->allow_concatenated;

  for (i = 1; i < argc; ++i) {
    const char* arg = argv[i];
    size_t arg_len = arg ? strlen(arg) : 0;

    if (arg_len == 0) {
      if (next_option_index >= MAX_OPTIONS - 2) {
        fprintf(stderr, "too many options passed\n");
        return COMMAND_INVALID;
      }
      params->not_input_indices[next_option_index++] = i;
      continue;
    }

    /* Input file entry. */
    if (after_dash_dash || arg[0] != '-' || arg_len == 1) {
      input_count++;
      if (params->longest_path_len < arg_len) params->longest_path_len = arg_len;
      continue;
    }

    if (next_option_index >= MAX_OPTIONS - 2) {
      fprintf(stderr, "too many options passed\n");
      return COMMAND_INVALID;
    }
    params->not_input_indices[next_option_index++] = i;

    if (arg_len == 2 && arg[1] == '-') {
      after_dash_dash = 1;
      continue;
    }

    if (arg[1] != '-') {
      size_t j;
      for (j = 1; j < arg_len; ++j) {
        char c = arg[j];
        if (c >= '0' && c <= '9') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = 1;
          params->quality = c - '0';
          continue;
        } else if (c == 'c') {
          if (params->write_to_stdout) {
            fprintf(stderr, "write to standard output already set\n");
            return COMMAND_INVALID;
          }
          params->write_to_stdout = 1;
          continue;
        } else if (c == 'd') {
          if (command_set || command != COMMAND_COMPRESS) {
            fprintf(stderr, "command already set when parsing -d\n");
            return COMMAND_INVALID;
          }
          command_set = 1;
          command = COMMAND_DECOMPRESS;
          continue;
        } else if (c == 'f') {
          if (params->force_overwrite) {
            fprintf(stderr, "force output overwrite already set\n");
            return COMMAND_INVALID;
          }
          params->force_overwrite = 1;
          continue;
        } else if (c == 'h') {
          return COMMAND_HELP;
        } else if (c == 'j' || c == 'k') {
          if (keep_set) {
            fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
            return COMMAND_INVALID;
          }
          keep_set = 1;
          params->junk_source = (c == 'j');
          continue;
        } else if (c == 'n') {
          if (!params->copy_stat) {
            fprintf(stderr, "argument --no-copy-stat / -n already set\n");
            return COMMAND_INVALID;
          }
          params->copy_stat = 0;
          continue;
        } else if (c == 's') {
          if (params->reject_uncompressible) {
            fprintf(stderr, "argument --squash / -s already set\n");
            return COMMAND_INVALID;
          }
          params->reject_uncompressible = 1;
          continue;
        } else if (c == 't') {
          if (command_set || command != COMMAND_COMPRESS) {
            fprintf(stderr, "command already set when parsing -t\n");
            return COMMAND_INVALID;
          }
          command_set = 1;
          command = COMMAND_TEST_INTEGRITY;
          continue;
        } else if (c == 'v') {
          if (params->verbosity > 0) {
            fprintf(stderr, "argument --verbose / -v already set\n");
            return COMMAND_INVALID;
          }
          params->verbosity = 1;
          continue;
        } else if (c == 'V') {
          return COMMAND_VERSION;
        } else if (c == 'Z') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = 1;
          params->quality = 11;
          continue;
        } else if (c == 'K') {
          if (params->allow_concatenated) {
            fprintf(stderr, "argument -K / --concatenated already set\n");
            return COMMAND_INVALID;
          }
          params->allow_concatenated = 1;
          continue;
        }
        /* o/q/w/C/D/S with parameter is expected */
        if (c != 'o' && c != 'q' && c != 'w' && c != 'C' && c != 'D' && c != 'S') {
          fprintf(stderr, "invalid argument -%c\n", c);
          return COMMAND_INVALID;
        }
        if (j + 1 != arg_len) {
          fprintf(stderr, "expected parameter for argument -%c\n", c);
          return COMMAND_INVALID;
        }
        i++;
        if (i == argc || !argv[i] || argv[i][0] == 0) {
          fprintf(stderr, "expected parameter for argument -%c\n", c);
          return COMMAND_INVALID;
        }
        if (next_option_index >= MAX_OPTIONS - 2) {
          fprintf(stderr, "too many options passed\n");
          return COMMAND_INVALID;
        }
        params->not_input_indices[next_option_index++] = i;
        if (c == 'o') {
          if (params->write_to_stdout) {
            fprintf(stderr, "write to standard output already set (-o)\n");
            return COMMAND_INVALID;
          }
          output_set = 1;
          params->output_path = argv[i];
        } else if (c == 'q') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = ParseInt(argv[i], 0, 11, &params->quality);
          if (!quality_set) {
            fprintf(stderr, "error parsing quality value [%s]\n", argv[i]);
            return COMMAND_INVALID;
          }
        } else if (c == 'w') {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(argv[i], 0, BR_MAX_WINDOW_BITS, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", argv[i]);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < BR_MIN_WINDOW_BITS) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, BR_MIN_WINDOW_BITS);
            return COMMAND_INVALID;
          }
        } else if (c == 'C') {
          if (comment_set) {
            fprintf(stderr, "comment already set\n");
            return COMMAND_INVALID;
          }
          comment_set = 1;
          if (!ParseBase64(argv[i], params->comment, &params->comment_len)) {
            fprintf(stderr, "invalid base64-encoded comment\n");
            return COMMAND_INVALID;
          }
        } else if (c == 'D') {
          if (params->dictionary_path) {
            fprintf(stderr, "dictionary path already set\n");
            return COMMAND_INVALID;
          }
          params->dictionary_path = argv[i];
        } else if (c == 'S') {
          if (suffix_set) {
            fprintf(stderr, "suffix already set\n");
            return COMMAND_INVALID;
          }
          suffix_set = 1;
          params->suffix = argv[i];
        }
      }
    } else {
      /* Double-dash. */
      arg = &arg[2];
      if (strcmp("best", arg) == 0) {
        if (quality_set) {
          fprintf(stderr, "quality already set\n");
          return COMMAND_INVALID;
        }
        quality_set = 1;
        params->quality = 11;
      } else if (strcmp("decompress", arg) == 0) {
        if (command_set || command != COMMAND_COMPRESS) {
          fprintf(stderr, "command already set when parsing --decompress\n");
          return COMMAND_INVALID;
        }
        command_set = 1;
        command = COMMAND_DECOMPRESS;
      } else if (strcmp("force", arg) == 0) {
        if (params->force_overwrite) {
          fprintf(stderr, "force output overwrite already set\n");
          return COMMAND_INVALID;
        }
        params->force_overwrite = 1;
      } else if (strcmp("help", arg) == 0) {
        return COMMAND_HELP;
      } else if (strcmp("keep", arg) == 0) {
        if (keep_set) {
          fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
          return COMMAND_INVALID;
        }
        keep_set = 1;
        params->junk_source = 0;
      } else if (strcmp("no-copy-stat", arg) == 0) {
        if (!params->copy_stat) {
          fprintf(stderr, "argument --no-copy-stat / -n already set\n");
          return COMMAND_INVALID;
        }
        params->copy_stat = 0;
      } else if (strcmp("rm", arg) == 0) {
        if (keep_set) {
          fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
          return COMMAND_INVALID;
        }
        keep_set = 1;
        params->junk_source = 1;
      } else if (strcmp("squash", arg) == 0) {
        if (params->reject_uncompressible) {
          fprintf(stderr, "argument --squash / -s already set\n");
          return COMMAND_INVALID;
        }
        params->reject_uncompressible = 1;
      } else if (strcmp("stdout", arg) == 0) {
        if (params->write_to_stdout) {
          fprintf(stderr, "write to standard output already set\n");
          return COMMAND_INVALID;
        }
        params->write_to_stdout = 1;
      } else if (strcmp("test", arg) == 0) {
        if (command_set || command != COMMAND_COMPRESS) {
          fprintf(stderr, "command already set when parsing --test\n");
          return COMMAND_INVALID;
        }
        command_set = 1;
        command = COMMAND_TEST_INTEGRITY;
      } else if (strcmp("verbose", arg) == 0) {
        if (params->verbosity > 0) {
          fprintf(stderr, "argument --verbose / -v already set\n");
          return COMMAND_INVALID;
        }
        params->verbosity = 1;
      } else if (strcmp("version", arg) == 0) {
        return COMMAND_VERSION;
      } else if (strcmp("concatenated", arg) == 0) {
        if (params->allow_concatenated) {
          fprintf(stderr, "argument -K / --concatenated already set\n");
          return COMMAND_INVALID;
        }
        params->allow_concatenated = 1;
      } else {
        /* key=value */
        const char* value = strrchr(arg, '=');
        size_t key_len;
        if (!value || value[1] == 0) {
          fprintf(stderr, "must pass the parameter as --%s=value\n", arg);
          return COMMAND_INVALID;
        }
        key_len = (size_t)(value - arg);
        value++;
        if (strncmp("comment", arg, key_len) == 0) {
          if (comment_set) {
            fprintf(stderr, "comment already set\n");
            return COMMAND_INVALID;
          }
          comment_set = 1;
          if (!ParseBase64(value, params->comment, &params->comment_len)) {
            fprintf(stderr, "invalid base64-encoded comment\n");
            return COMMAND_INVALID;
          }
        } else if (strncmp("lgwin", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, BR_MAX_WINDOW_BITS, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < BR_MIN_WINDOW_BITS) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, BR_MIN_WINDOW_BITS);
            return COMMAND_INVALID;
          }
        } else if (strncmp("large_window", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, BR_LARGE_MAX_WINDOW_BITS, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < BR_MIN_WINDOW_BITS) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, BR_MIN_WINDOW_BITS);
            return COMMAND_INVALID;
          }
        } else if (strncmp("output", arg, key_len) == 0) {
          if (params->write_to_stdout) {
            fprintf(stderr, "write to standard output already set (-o)\n");
            return COMMAND_INVALID;
          }
          output_set = 1;
          params->output_path = value;
        } else if (strncmp("quality", arg, key_len) == 0) {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = ParseInt(value, 0, 11, &params->quality);
          if (!quality_set) {
            fprintf(stderr, "error parsing quality value [%s]\n", value);
            return COMMAND_INVALID;
          }
        } else if (strncmp("suffix", arg, key_len) == 0) {
          if (suffix_set) {
            fprintf(stderr, "suffix already set\n");
            return COMMAND_INVALID;
          }
          suffix_set = 1;
          params->suffix = value;
        } else if (strncmp("dictionary", arg, key_len) == 0) {
          if (params->dictionary_path) {
            fprintf(stderr, "dictionary path already set\n");
            return COMMAND_INVALID;
          }
          params->dictionary_path = value;
        } else {
          fprintf(stderr, "invalid parameter: [%s]\n", arg);
          return COMMAND_INVALID;
        }
      }
    }
  }
  (void)output_set;
  (void)alias_stdout;
  (void)alias_concat;

  params->input_count = input_count;
  params->decompress = (command == COMMAND_DECOMPRESS);
  params->test_integrity = (command == COMMAND_TEST_INTEGRITY);

  /* Consistency checks (observed to fail silently). */
  if (params->write_to_stdout && input_count > 1) return COMMAND_INVALID;
  if (params->allow_concatenated && command != COMMAND_DECOMPRESS) return COMMAND_INVALID;
  if (params->allow_concatenated && params->comment_len > 0) return COMMAND_INVALID;
  if (params->reject_uncompressible && params->write_to_stdout) return COMMAND_INVALID;
  if (command == COMMAND_TEST_INTEGRITY && (params->write_to_stdout || params->output_path)) return COMMAND_INVALID;
  return command;
}

static int64_t FileSize(const char* path) {
  FILE* f = fopen(path, "rb");
  int64_t retval;
  if (f == NULL) return -1;
  if (fseek(f, 0L, SEEK_END) != 0) {
    fclose(f);
    return -1;
  }
  retval = ftell(f);
  if (fclose(f) != 0) return -1;
  return retval;
}

static void CopyStat(const char* input_path, const char* output_path) {
  struct stat statbuf;
  struct utimbuf times;
  int res;
  if (input_path == 0 || output_path == 0) return;
  if (stat(input_path, &statbuf) != 0) return;
  times.actime = statbuf.st_atime;
  times.modtime = statbuf.st_mtime;
  utime(output_path, &times);
  res = chmod(output_path, statbuf.st_mode & (S_IRWXU | S_IRWXG | S_IRWXO));
  if (res != 0) {
    fprintf(stderr, "setting access bits failed for [%s]: %s\n", output_path, strerror(errno));
  }
  res = chown(output_path, (uid_t)-1, statbuf.st_gid);
  if (res != 0) {
    fprintf(stderr, "setting group failed for [%s]: %s\n", output_path, strerror(errno));
  }
  res = chown(output_path, statbuf.st_uid, (gid_t)-1);
  if (res != 0) {
    fprintf(stderr, "setting user failed for [%s]: %s\n", output_path, strerror(errno));
  }
}

static int NextFile(Context* context) {
  const char* arg;
  size_t arg_len;

  context->iterator++;

  if (context->input_count == 0) {
    if (context->iterator > 1) return 0;
    context->current_input_path = NULL;
    context->input_file_length = -1;
    context->current_output_path = context->output_path;
    return 1;
  }

  while (context->iterator == context->not_input_indices[context->ignore]) {
    context->iterator++;
    context->ignore++;
  }

  if (context->iterator >= context->argc) return 0;

  arg = context->argv[context->iterator];
  arg_len = strlen(arg);
  if (arg_len == 1 && arg[0] == '-') {
    context->current_input_path = NULL;
    context->input_file_length = -1;
    context->current_output_path = context->output_path;
    return 1;
  }

  context->current_input_path = arg;
  context->input_file_length = FileSize(arg);
  context->current_output_path = context->output_path;

  if (context->output_path) return 1;
  if (context->write_to_stdout) return 1;

  strcpy(context->modified_path, arg);
  context->current_output_path = context->modified_path;
  if (context->decompress) {
    size_t suffix_len = strlen(context->suffix);
    char* name = (char*)FileName(context->modified_path);
    size_t name_len = strlen(name);
    char* name_end;
    if (name_len <= suffix_len) {
      fprintf(stderr, "empty output file name for [%s] input file\n", arg);
      context->iterator_error = 1;
      return 0;
    }
    name_end = name + name_len - suffix_len;
    if (strcmp(name_end, context->suffix) != 0) {
      fprintf(stderr, "input file [%s] suffix mismatch\n", arg);
      context->iterator_error = 1;
      return 0;
    }
    name_end[0] = 0;
    return 1;
  } else {
    strcpy(context->modified_path + arg_len, context->suffix);
    return 1;
  }
}

static int OpenInputFile(const char* input_path, FILE** f) {
  *f = NULL;
  if (!input_path) {
    *f = fdopen(STDIN_FILENO, "rb");
    return 1;
  }
  *f = fopen(input_path, "rb");
  if (!*f) {
    fprintf(stderr, "failed to open input file [%s]: %s\n", PrintablePath(input_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int OpenOutputFile(const char* output_path, FILE** f, int force) {
  int fd;
  *f = NULL;
  if (!output_path) {
    *f = fdopen(STDOUT_FILENO, "wb");
    return 1;
  }
  fd = open(output_path, O_CREAT | (force ? 0 : O_EXCL) | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
  if (fd < 0) {
    fprintf(stderr, "failed to open output file [%s]: %s\n", PrintablePath(output_path), strerror(errno));
    return 0;
  }
  *f = fdopen(fd, "wb");
  if (!*f) {
    fprintf(stderr, "failed to open output file [%s]: %s\n", PrintablePath(output_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int OpenFiles(Context* context) {
  int is_ok = OpenInputFile(context->current_input_path, &context->fin);
  if (!context->test_integrity && is_ok) {
    is_ok = OpenOutputFile(context->current_output_path, &context->fout, context->force_overwrite);
  }
  return is_ok;
}

static int CloseFiles(Context* context, int success) {
  int is_ok = 1;
  if (!context->test_integrity && context->fout) {
    if (!success && context->current_output_path) {
      unlink(context->current_output_path);
    }
    if (fclose(context->fout) != 0) {
      if (success) {
        fprintf(stderr, "fclose failed [%s]: %s\n", PrintablePath(context->current_output_path), strerror(errno));
      }
      is_ok = 0;
    }
    if (success && is_ok && context->copy_stat) {
      CopyStat(context->current_input_path, context->current_output_path);
    }
  }

  if (context->fin) {
    if (fclose(context->fin) != 0) {
      if (is_ok) {
        fprintf(stderr, "fclose failed [%s]: %s\n", PrintablePath(context->current_input_path), strerror(errno));
      }
      is_ok = 0;
    }
  }
  if (success && context->junk_source && context->current_input_path) {
    unlink(context->current_input_path);
  }

  context->fin = NULL;
  context->fout = NULL;
  return is_ok;
}

static void InitializeBuffers(Context* context) {
  context->available_in = 0;
  context->next_in = NULL;
  context->available_out = kFileBufferSize;
  context->next_out = context->output;
  context->total_in = 0;
  context->total_out = 0;
  if (context->verbosity > 0) {
    context->start_time = clock();
  }
}

static int HasMoreInput(Context* context) {
  return feof(context->fin) ? 0 : 1;
}

static int ProvideInput(Context* context) {
  context->available_in = fread(context->input, 1, kFileBufferSize, context->fin);
  context->total_in += context->available_in;
  context->next_in = context->input;
  if (ferror(context->fin)) {
    fprintf(stderr, "failed to read input [%s]: %s\n", PrintablePath(context->current_input_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int WriteOutput(Context* context) {
  size_t out_size = (size_t)(context->next_out - context->output);
  context->total_out += out_size;
  if (out_size == 0) return 1;
  if (context->test_integrity) return 1;

  fwrite(context->output, 1, out_size, context->fout);
  if (ferror(context->fout)) {
    fprintf(stderr, "failed to write output [%s]: %s\n", PrintablePath(context->current_output_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int ProvideOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = kFileBufferSize;
  context->next_out = context->output;
  return 1;
}

static int FlushOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = 0;
  return 1;
}

static void PrintBytes(size_t value) {
  if (value < 1024) {
    fprintf(stderr, "%d B", (int)value);
  } else if (value < 1048576) {
    fprintf(stderr, "%0.3f KiB", (double)value / 1024.0);
  } else if (value < 1073741824) {
    fprintf(stderr, "%0.3f MiB", (double)value / 1048576.0);
  } else {
    fprintf(stderr, "%0.3f GiB", (double)value / 1073741824.0);
  }
}

static void PrintFileProcessingProgress(Context* context) {
  fprintf(stderr, "[%s]: ", PrintablePath(context->current_input_path));
  PrintBytes(context->total_in);
  fprintf(stderr, " -> ");
  PrintBytes(context->total_out);
  fprintf(stderr, " in %1.2f sec", (double)(context->end_time - context->start_time) / CLOCKS_PER_SEC);
}

/* ---------------- decompression ---------------- */

static size_t DecoderRead(void* opaque, const uint8_t** buf) {
  Context* context = (Context*)opaque;
  if (!HasMoreInput(context)) { context->decoder_eof = 1; return 0; }
  if (!ProvideInput(context)) { context->read_error = 1; return 0; }
  *buf = context->next_in;
  return context->available_in;
}

/* Emulates the decoder writing into the CLI's output buffer: flush when full and more pending. */
static int DecoderWrite(void* opaque, const uint8_t* data, size_t len) {
  Context* context = (Context*)opaque;
  while (len > 0) {
    size_t n;
    if (context->available_out == 0) {
      if (!ProvideOutput(context)) { context->write_error = 1; return 0; }
    }
    n = BR_MIN(len, context->available_out);
    memcpy(context->next_out, data, n);
    context->next_out += n;
    context->available_out -= n;
    data += n;
    len -= n;
  }
  return 1;
}

static int DecoderMetaStart(void* opaque, size_t size) {
  Context* context = (Context*)opaque;
  if (context->comment_len == 0) return 1;
  if (context->comment_state != 0) return 1;  /* only first metadata block is checked */
  context->comment_state = 1;
  context->comment_pos = 0;
  if (size != context->comment_len) { context->comment_state = -1; return 0; }
  return 1;
}

static int DecoderMetaChunk(void* opaque, const uint8_t* data, size_t len) {
  Context* context = (Context*)opaque;
  size_t i;
  if (context->comment_state != 1) return 1;
  for (i = 0; i < len; i++) {
    if (context->comment_pos >= context->comment_len || data[i] != context->comment[context->comment_pos]) {
      context->comment_state = -1;
      return 0;
    }
    context->comment_pos++;
  }
  return 1;
}

static int DecoderMetaEnd(void* opaque) {
  Context* context = (Context*)opaque;
  if (context->comment_state == 1) {
    if (context->comment_pos != context->comment_len) { context->comment_state = -1; return 0; }
    context->comment_state = 2;
  }
  return 1;
}

static int DecompressFile(Context* context) {
  BrDecoderIO io;
  BrDecoderStatus status;
  int first = 1;
  InitializeBuffers(context);
  context->read_error = 0;
  context->write_error = 0;
  context->comment_state = 0;
  context->decoder_eof = 0;
  memset(&io, 0, sizeof(io));
  io.read = DecoderRead;
  io.write = DecoderWrite;
  io.meta_start = DecoderMetaStart;
  io.meta_chunk = DecoderMetaChunk;
  io.meta_end = DecoderMetaEnd;
  io.opaque = context;
  io.custom_dict = context->dictionary;
  io.custom_dict_size = context->dictionary_size;
  for (;;) {
    /* Pre-provide input remaining from the previous stream, if any. */
    (void)first;
    br_decode_stream_ex(&io, &status, context->available_in ? context->next_in : NULL, context->available_in);
    context->next_in = status.rest;
    context->available_in = status.rest_len;
    if (status.result == BR_DEC_SUCCESS) {
      int has_more_input;
      if (!FlushOutput(context)) return 0;
      if (context->available_in == 0 && HasMoreInput(context)) {
        if (!ProvideInput(context)) return 0;
      }
      has_more_input = context->available_in != 0;
      if (has_more_input) {
        if (context->allow_concatenated) {
          if (context->verbosity > 0) fprintf(stderr, "extra input\n");
          context->available_out = kFileBufferSize;
          context->next_out = context->output;
          first = 0;
          continue;
        }
        fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
        if (context->verbosity > 0) fprintf(stderr, "reason: extra input\n");
        return 0;
      }
      if (context->verbosity > 0) {
        context->end_time = clock();
        fprintf(stderr, "Decompressed ");
        PrintFileProcessingProgress(context);
        fprintf(stderr, "\n");
      }
      if (context->comment_len > 0 && context->comment_state == 0) {
        fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
        if (context->verbosity > 0) fprintf(stderr, "reason: comment mismatch\n");
      }
      return 1;
    } else if (status.result == BR_DEC_NEEDS_MORE_INPUT) {
      if (context->read_error) return 0;
      fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
      if (context->verbosity > 0) fprintf(stderr, "reason: truncated input\n");
      return 0;
    } else if (status.result == BR_DEC_ABORT_OUTPUT) {
      return 0;
    } else if (status.result == BR_DEC_ABORT_METADATA) {
      fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
      if (context->verbosity > 0) fprintf(stderr, "reason: comment mismatch\n");
      return 0;
    } else {
      fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
      if (context->verbosity > 0) {
        fprintf(stderr, "reason: %s (%d)\n", br_decoder_error_string(status.result), status.result);
      }
      return 0;
    }
  }
}

static int DecompressFiles(Context* context) {
  while (NextFile(context)) {
    int is_ok = 1;
    is_ok = OpenFiles(context);
    if (is_ok) is_ok = DecompressFile(context);
    if (!CloseFiles(context, is_ok)) is_ok = 0;
    if (!is_ok) return 0;
  }
  return 1;
}

/* ---------------- compression ---------------- */

static int CompressFile(Context* context, BrEncoder* s) {
  int is_eof = 0;
  InitializeBuffers(context);
  if (context->comment_len > 0) {
    size_t comment_in = context->comment_len;
    const uint8_t* comment_ptr = context->comment;
    br_encoder_emit_metadata(s, &comment_in, &comment_ptr, &context->available_out, &context->next_out);
  }
  for (;;) {
    if (context->available_in == 0 && !is_eof) {
      if (!ProvideInput(context)) return 0;
      is_eof = !HasMoreInput(context);
    }

    if (!br_encoder_compress_stream(s, is_eof ? BR_OP_FINISH : BR_OP_PROCESS,
        &context->available_in, &context->next_in, &context->available_out, &context->next_out)) {
      fprintf(stderr, "failed to compress data [%s]\n", PrintablePath(context->current_input_path));
      return 0;
    }

    if (context->available_out == 0) {
      if (!ProvideOutput(context)) return 0;
    }

    if (br_encoder_is_finished(s)) {
      if (!FlushOutput(context)) return 0;
      if (context->verbosity > 0) {
        context->end_time = clock();
        fprintf(stderr, "Compressed ");
        PrintFileProcessingProgress(context);
        fprintf(stderr, "\n");
      }
      return 1;
    }
  }
}

static int CompressFiles(Context* context) {
  while (NextFile(context)) {
    int is_ok = 1;
    int rejected = 0;
    BrEncoder* s = br_encoder_create();
    if (!s) {
      fprintf(stderr, "out of memory\n");
      return 0;
    }
    br_encoder_set_quality(s, context->quality);
    if (context->lgwin > 0) {
      if (context->lgwin > BR_MAX_WINDOW_BITS) {
        br_encoder_set_large_window(s, 1);
      }
      br_encoder_set_lgwin(s, context->lgwin);
    } else {
      uint32_t lgwin = DEFAULT_LGWIN;
      if (context->input_file_length >= 0) {
        lgwin = BR_MIN_WINDOW_BITS;
        while (BR_MAX_BACKWARD_LIMIT(lgwin) < (uint64_t)context->input_file_length) {
          lgwin++;
          if (lgwin == BR_MAX_WINDOW_BITS) break;
        }
      }
      br_encoder_set_lgwin(s, (int)lgwin);
    }
    if (context->input_file_length > 0) {
      uint32_t size_hint = context->input_file_length < (1 << 30) ? (uint32_t)context->input_file_length : (1u << 30);
      br_encoder_set_size_hint(s, size_hint);
    }
    if (context->prepared_dictionary) {
      br_encoder_attach_dictionary(s, context->prepared_dictionary);
    }
    is_ok = OpenFiles(context);
    if (is_ok && !context->current_output_path && !context->force_overwrite && isatty(STDOUT_FILENO)) {
      fprintf(stderr, "Use -h help. Use -f to force output to a terminal.\n");
      is_ok = 0;
    }
    if (is_ok) is_ok = CompressFile(context, s);
    br_encoder_destroy(s);
    if (is_ok && context->reject_uncompressible && context->total_out > context->total_in) {
      rejected = 1;
      if (context->verbosity > 0) fprintf(stderr, "Output is larger than input\n");
    }
    if (rejected) {
      /* Remove destination, keep source. */
      int junk = context->junk_source;
      context->junk_source = 0;
      if (!CloseFiles(context, 1)) is_ok = 0;
      context->junk_source = junk;
      if (context->current_output_path) unlink(context->current_output_path);
    } else {
      if (!CloseFiles(context, is_ok)) is_ok = 0;
    }
    if (!is_ok) return 0;
  }
  return 1;
}

static int ReadDictionary(Context* context, Command command) {
  static const int kMaxDictionarySize = 50331660;
  FILE* f;
  int64_t file_size_64;
  uint8_t* buffer;
  size_t bytes_read;

  if (context->dictionary_path == NULL) return 1;
  f = fopen(context->dictionary_path, "rb");
  if (f == NULL) {
    fprintf(stderr, "failed to open dictionary file [%s]: %s\n", PrintablePath(context->dictionary_path), strerror(errno));
    return 0;
  }

  file_size_64 = FileSize(context->dictionary_path);
  if (file_size_64 == -1) {
    fprintf(stderr, "could not get size of dictionary file [%s]", PrintablePath(context->dictionary_path));
    fclose(f);
    return 0;
  }

  if (file_size_64 > kMaxDictionarySize) {
    fprintf(stderr, "dictionary [%s] is larger than maximum allowed: %d\n", PrintablePath(context->dictionary_path), kMaxDictionarySize);
    fclose(f);
    return 0;
  }
  context->dictionary_size = (size_t)file_size_64;

  buffer = (uint8_t*)malloc(context->dictionary_size + 1);
  if (!buffer) {
    fprintf(stderr, "could not read dictionary: out of memory\n");
    fclose(f);
    return 0;
  }
  bytes_read = fread(buffer, sizeof(uint8_t), context->dictionary_size, f);
  if (bytes_read != context->dictionary_size) {
    free(buffer);
    fprintf(stderr, "failed to read dictionary [%s]: %s\n", PrintablePath(context->dictionary_path), strerror(errno));
    fclose(f);
    return 0;
  }
  fclose(f);
  context->dictionary = buffer;

  if (command == COMMAND_COMPRESS) {
    context->prepared_dictionary = br_encoder_prepare_dictionary(context->dictionary, context->dictionary_size, 11);
    if (context->prepared_dictionary == NULL) {
      fprintf(stderr, "failed to prepare dictionary [%s]\n", PrintablePath(context->dictionary_path));
      return 0;
    }
  }
  return 1;
}

int main(int argc, char** argv) {
  Command command;
  Context context;
  int is_ok = 1;
  int i;

  br_init_cmd_lut();

  memset(&context, 0, sizeof(context));
  context.quality = 11;
  context.lgwin = -1;
  context.verbosity = 0;
  context.force_overwrite = 0;
  context.junk_source = 0;
  context.reject_uncompressible = 0;
  context.copy_stat = 1;
  context.test_integrity = 0;
  context.write_to_stdout = 0;
  context.decompress = 0;
  context.large_window = 0;
  context.allow_concatenated = 0;
  context.output_path = NULL;
  context.dictionary_path = NULL;
  context.suffix = DEFAULT_SUFFIX;
  context.comment_len = 0;
  for (i = 0; i < MAX_OPTIONS; ++i) context.not_input_indices[i] = 0;
  context.longest_path_len = 1;
  context.input_count = 0;

  context.argc = argc;
  context.argv = argv;
  context.dictionary = NULL;
  context.dictionary_size = 0;
  context.prepared_dictionary = NULL;
  context.modified_path = NULL;
  context.iterator = 0;
  context.ignore = 0;
  context.iterator_error = 0;
  context.buffer = NULL;
  context.current_input_path = NULL;
  context.current_output_path = NULL;
  context.fin = NULL;
  context.fout = NULL;

  command = ParseParams(&context);

  if (command == COMMAND_COMPRESS || command == COMMAND_DECOMPRESS || command == COMMAND_TEST_INTEGRITY) {
    if (is_ok && context.dictionary_path) is_ok = ReadDictionary(&context, command);
    if (is_ok) {
      size_t modified_path_len = context.longest_path_len + strlen(context.suffix) + 1;
      context.modified_path = (char*)malloc(modified_path_len);
      context.buffer = (uint8_t*)malloc(kFileBufferSize * 2);
      if (!context.modified_path || !context.buffer) {
        fprintf(stderr, "out of memory\n");
        is_ok = 0;
      } else {
        context.input = context.buffer;
        context.output = context.buffer + kFileBufferSize;
      }
    }
  }

  if (!is_ok) command = COMMAND_NOOP;

  switch (command) {
    case COMMAND_NOOP:
      break;
    case COMMAND_VERSION:
      PrintVersion();
      break;
    case COMMAND_COMPRESS:
      is_ok = CompressFiles(&context);
      break;
    case COMMAND_DECOMPRESS:
    case COMMAND_TEST_INTEGRITY:
      is_ok = DecompressFiles(&context);
      break;
    case COMMAND_HELP:
    case COMMAND_INVALID:
    default:
      is_ok = (command == COMMAND_HELP);
      PrintHelp(FileName(argv[0]), !is_ok);
      break;
  }

  if (context.iterator_error) is_ok = 0;

  br_encoder_destroy_prepared_dictionary(context.prepared_dictionary);
  free(context.dictionary);
  free(context.modified_path);
  free(context.buffer);

  if (!is_ok) exit(1);
  return 0;
}
EOF
echo written"}

actions.command:
cd /workspace/src && cat > cli.c <<'EOF'
/* Command line interface, modelled after the observed behaviour of the brotli tool. */
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>
#include <utime.h>

#include "common/platform.h"
#include "common/prefix.h"
#include "dec/decode.h"
#include "enc/encode.h"

#define DEFAULT_LGWIN 24
#define DEFAULT_SUFFIX ".br"
#define MAX_OPTIONS 24
#define MAX_COMMENT_LEN 80

typedef enum {
  COMMAND_COMPRESS,
  COMMAND_DECOMPRESS,
  COMMAND_HELP,
  COMMAND_INVALID,
  COMMAND_TEST_INTEGRITY,
  COMMAND_NOOP,
  COMMAND_VERSION
} Command;

typedef struct {
  /* Parameters */
  int quality;
  int lgwin;
  int verbosity;
  int force_overwrite;
  int junk_source;
  int reject_uncompressible;
  int copy_stat;
  int write_to_stdout;
  int test_integrity;
  int decompress;
  int large_window;
  int allow_concatenated;
  const char* output_path;
  const char* dictionary_path;
  const char* suffix;
  uint8_t comment[MAX_COMMENT_LEN];
  size_t comment_len;
  int not_input_indices[MAX_OPTIONS];
  size_t longest_path_len;
  size_t input_count;

  /* Inner state */
  int argc;
  char** argv;
  uint8_t* dictionary;
  size_t dictionary_size;
  BrPreparedDictionary* prepared_dictionary;
  char* modified_path;
  int iterator;
  int ignore;
  int iterator_error;
  uint8_t* buffer;
  uint8_t* input;
  uint8_t* output;
  const char* current_input_path;
  const char* current_output_path;
  int64_t input_file_length;
  FILE* fin;
  FILE* fout;

  /* I/O buffers */
  size_t available_in;
  const uint8_t* next_in;
  size_t available_out;
  uint8_t* next_out;

  /* Reporting */
  size_t total_in;
  size_t total_out;
  clock_t start_time;
  clock_t end_time;

  /* decoder helpers */
  int read_error;
  int write_error;
  int comment_state;   /* 0: not seen, 1: checking first metadata, 2: done (ok), -1: mismatch */
  size_t comment_pos;
  int decoder_eof;
} Context;

static const size_t kFileBufferSize = 1 << 19;

static void PrintVersion(void) {
  fprintf(stdout, "brotli %d.%d.%d\n", 1, 2, 0);
}

static void PrintHelp(const char* name, int error) {
  /* Observed: help on success goes to stderr, on error to stdout. */
  FILE* media = error ? stdout : stderr;
  fprintf(media,
"Usage: %s [OPTION]... [FILE]...\n",
          name);
  fprintf(media,
"Options:\n"
"  -#                          compression level (0-9)\n"
"  -c, --stdout                write on standard output\n"
"  -d, --decompress            decompress\n"
"  -f, --force                 force output file overwrite\n"
"  -h, --help                  display this help and exit\n"
"  -j, --rm                    remove source file(s)\n"
"  -s, --squash                remove destination file if larger than source\n"
"  -k, --keep                  keep source file(s) (default)\n"
"  -n, --no-copy-stat          do not copy source file(s) attributes\n"
"  -o FILE, --output=FILE      output file (only if 1 input file)\n");
  fprintf(media,
"  -q NUM, --quality=NUM       compression level (0-11)\n"
"  -t, --test                  test compressed file integrity\n"
"  -v, --verbose               verbose mode\n"
"  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)\n"
"                              window size = 2**NUM - 16\n"
"                              0 lets compressor choose the optimal value\n"
"  --large_window=NUM          use incompatible large-window brotli\n"
"                              bitstream with window size (0, 10-30)\n"
"                              WARNING: this format is not compatible\n"
"                              with brotli RFC 7932 and may not be\n"
"                              decodable with regular brotli decoders\n");
  fprintf(media,
"  -C B64, --comment=B64       set comment; argument is base64-decoded first;\n"
"                              (maximal decoded length: 80)\n"
"                              when decoding: check stream comment;\n"
"                              when encoding: embed comment (fingerprint)\n"
"  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary\n"
"  -K, --concatenated          allows concatenated brotli streams as input\n"
"  -S SUF, --suffix=SUF        output file suffix (default:'%s')\n",
          DEFAULT_SUFFIX);
  fprintf(media,
"  -V, --version               display version and exit\n"
"  -Z, --best                  use best compression level (11) (default)\n"
"Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.\n"
"With no FILE, or when FILE is -, read standard input.\n"
"All arguments after '--' are treated as files.\n");
}

static const char* FileName(const char* path) {
  const char* separator_position = strrchr(path, '/');
  if (separator_position) path = separator_position + 1;
  separator_position = strrchr(path, '\\');
  if (separator_position) path = separator_position + 1;
  return path;
}

static const char* PrintablePath(const char* path) {
  return path ? path : "con";
}

static int ParseInt(const char* s, int low, int high, int* result) {
  int value = 0;
  int i;
  for (i = 0; i < 5; ++i) {
    char c = s[i];
    if (c == 0) break;
    if (s[i] >= '0' && s[i] <= '9') {
      value = (10 * value) + (c - '0');
    } else {
      return 0;
    }
  }
  if (i == 0) return 0;
  if (i > 1 && s[0] == '0') return 0;
  if (s[i] != 0) return 0;
  if (value < low || value > high) return 0;
  *result = value;
  return 1;
}

static int ParseBase64(const char* s, uint8_t* out, size_t* out_len) {
  uint32_t acc = 0;
  int bits = 0;
  int pad = 0;
  size_t len = 0;
  for (; *s; ++s) {
    char c = *s;
    int v;
    if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
    if (c == '=') {
      pad++;
      if (pad > 2) return 0;
      continue;
    }
    if (pad > 0) return 0;
    if (c >= 'A' && c <= 'Z') v = c - 'A';
    else if (c >= 'a' && c <= 'z') v = c - 'a' + 26;
    else if (c >= '0' && c <= '9') v = c - '0' + 52;
    else if (c == '+' || c == '-') v = 62;
    else if (c == '/' || c == '_') v = 63;
    else return 0;
    acc = (acc << 6) | (uint32_t)v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      if (len >= MAX_COMMENT_LEN) return 0;
      out[len++] = (uint8_t)((acc >> bits) & 0xFF);
    }
  }
  *out_len = len;
  return 1;
}

/* Detect special program name aliases. */
static Command ParseAlias(const char* name, Context* params) {
  const char* unbrotli = "unbrotli";
  const char* brcat = "brcat";
  size_t unbrotli_len = strlen(unbrotli);
  size_t brcat_len = strlen(brcat);
  name = FileName(name);
  if (strncmp(name, unbrotli, unbrotli_len) == 0) {
    char terminator = name[unbrotli_len];
    if (terminator == 0 || terminator == '.') return COMMAND_DECOMPRESS;
  }
  if (strncmp(name, brcat, brcat_len) == 0) {
    char terminator = name[brcat_len];
    if (terminator == 0 || terminator == '.') {
      params->write_to_stdout = 1;
      params->allow_concatenated = 1;
      return COMMAND_DECOMPRESS;
    }
  }
  return COMMAND_COMPRESS;
}

static Command ParseParams(Context* params) {
  int argc = params->argc;
  char** argv = params->argv;
  int i;
  int next_option_index = 0;
  size_t input_count = 0;
  int command_set = 0;
  int quality_set = 0;
  int output_set = 0;
  int keep_set = 0;
  int lgwin_set = 0;
  int suffix_set = 0;
  int comment_set = 0;
  int after_dash_dash = 0;
  Command command = ParseAlias(argv[0], params);
  int alias_stdout = params->write_to_stdout;
  int alias_concat = params->allow_concatenated;

  for (i = 1; i < argc; ++i) {
    const char* arg = argv[i];
    size_t arg_len = arg ? strlen(arg) : 0;

    if (arg_len == 0) {
      if (next_option_index >= MAX_OPTIONS - 2) {
        fprintf(stderr, "too many options passed\n");
        return COMMAND_INVALID;
      }
      params->not_input_indices[next_option_index++] = i;
      continue;
    }

    /* Input file entry. */
    if (after_dash_dash || arg[0] != '-' || arg_len == 1) {
      input_count++;
      if (params->longest_path_len < arg_len) params->longest_path_len = arg_len;
      continue;
    }

    if (next_option_index >= MAX_OPTIONS - 2) {
      fprintf(stderr, "too many options passed\n");
      return COMMAND_INVALID;
    }
    params->not_input_indices[next_option_index++] = i;

    if (arg_len == 2 && arg[1] == '-') {
      after_dash_dash = 1;
      continue;
    }

    if (arg[1] != '-') {
      size_t j;
      for (j = 1; j < arg_len; ++j) {
        char c = arg[j];
        if (c >= '0' && c <= '9') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = 1;
          params->quality = c - '0';
          continue;
        } else if (c == 'c') {
          if (params->write_to_stdout) {
            fprintf(stderr, "write to standard output already set\n");
            return COMMAND_INVALID;
          }
          params->write_to_stdout = 1;
          continue;
        } else if (c == 'd') {
          if (command_set || command != COMMAND_COMPRESS) {
            fprintf(stderr, "command already set when parsing -d\n");
            return COMMAND_INVALID;
          }
          command_set = 1;
          command = COMMAND_DECOMPRESS;
          continue;
        } else if (c == 'f') {
          if (params->force_overwrite) {
            fprintf(stderr, "force output overwrite already set\n");
            return COMMAND_INVALID;
          }
          params->force_overwrite = 1;
          continue;
        } else if (c == 'h') {
          return COMMAND_HELP;
        } else if (c == 'j' || c == 'k') {
          if (keep_set) {
            fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
            return COMMAND_INVALID;
          }
          keep_set = 1;
          params->junk_source = (c == 'j');
          continue;
        } else if (c == 'n') {
          if (!params->copy_stat) {
            fprintf(stderr, "argument --no-copy-stat / -n already set\n");
            return COMMAND_INVALID;
          }
          params->copy_stat = 0;
          continue;
        } else if (c == 's') {
          if (params->reject_uncompressible) {
            fprintf(stderr, "argument --squash / -s already set\n");
            return COMMAND_INVALID;
          }
          params->reject_uncompressible = 1;
          continue;
        } else if (c == 't') {
          if (command_set || command != COMMAND_COMPRESS) {
            fprintf(stderr, "command already set when parsing -t\n");
            return COMMAND_INVALID;
          }
          command_set = 1;
          command = COMMAND_TEST_INTEGRITY;
          continue;
        } else if (c == 'v') {
          if (params->verbosity > 0) {
            fprintf(stderr, "argument --verbose / -v already set\n");
            return COMMAND_INVALID;
          }
          params->verbosity = 1;
          continue;
        } else if (c == 'V') {
          return COMMAND_VERSION;
        } else if (c == 'Z') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = 1;
          params->quality = 11;
          continue;
        } else if (c == 'K') {
          if (params->allow_concatenated) {
            fprintf(stderr, "argument -K / --concatenated already set\n");
            return COMMAND_INVALID;
          }
          params->allow_concatenated = 1;
          continue;
        }
        /* o/q/w/C/D/S with parameter is expected */
        if (c != 'o' && c != 'q' && c != 'w' && c != 'C' && c != 'D' && c != 'S') {
          fprintf(stderr, "invalid argument -%c\n", c);
          return COMMAND_INVALID;
        }
        if (j + 1 != arg_len) {
          fprintf(stderr, "expected parameter for argument -%c\n", c);
          return COMMAND_INVALID;
        }
        i++;
        if (i == argc || !argv[i] || argv[i][0] == 0) {
          fprintf(stderr, "expected parameter for argument -%c\n", c);
          return COMMAND_INVALID;
        }
        if (next_option_index >= MAX_OPTIONS - 2) {
          fprintf(stderr, "too many options passed\n");
          return COMMAND_INVALID;
        }
        params->not_input_indices[next_option_index++] = i;
        if (c == 'o') {
          if (params->write_to_stdout) {
            fprintf(stderr, "write to standard output already set (-o)\n");
            return COMMAND_INVALID;
          }
          output_set = 1;
          params->output_path = argv[i];
        } else if (c == 'q') {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = ParseInt(argv[i], 0, 11, &params->quality);
          if (!quality_set) {
            fprintf(stderr, "error parsing quality value [%s]\n", argv[i]);
            return COMMAND_INVALID;
          }
        } else if (c == 'w') {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(argv[i], 0, BR_MAX_WINDOW_BITS, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", argv[i]);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < BR_MIN_WINDOW_BITS) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, BR_MIN_WINDOW_BITS);
            return COMMAND_INVALID;
          }
        } else if (c == 'C') {
          if (comment_set) {
            fprintf(stderr, "comment already set\n");
            return COMMAND_INVALID;
          }
          comment_set = 1;
          if (!ParseBase64(argv[i], params->comment, &params->comment_len)) {
            fprintf(stderr, "invalid base64-encoded comment\n");
            return COMMAND_INVALID;
          }
        } else if (c == 'D') {
          if (params->dictionary_path) {
            fprintf(stderr, "dictionary path already set\n");
            return COMMAND_INVALID;
          }
          params->dictionary_path = argv[i];
        } else if (c == 'S') {
          if (suffix_set) {
            fprintf(stderr, "suffix already set\n");
            return COMMAND_INVALID;
          }
          suffix_set = 1;
          params->suffix = argv[i];
        }
      }
    } else {
      /* Double-dash. */
      arg = &arg[2];
      if (strcmp("best", arg) == 0) {
        if (quality_set) {
          fprintf(stderr, "quality already set\n");
          return COMMAND_INVALID;
        }
        quality_set = 1;
        params->quality = 11;
      } else if (strcmp("decompress", arg) == 0) {
        if (command_set || command != COMMAND_COMPRESS) {
          fprintf(stderr, "command already set when parsing --decompress\n");
          return COMMAND_INVALID;
        }
        command_set = 1;
        command = COMMAND_DECOMPRESS;
      } else if (strcmp("force", arg) == 0) {
        if (params->force_overwrite) {
          fprintf(stderr, "force output overwrite already set\n");
          return COMMAND_INVALID;
        }
        params->force_overwrite = 1;
      } else if (strcmp("help", arg) == 0) {
        return COMMAND_HELP;
      } else if (strcmp("keep", arg) == 0) {
        if (keep_set) {
          fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
          return COMMAND_INVALID;
        }
        keep_set = 1;
        params->junk_source = 0;
      } else if (strcmp("no-copy-stat", arg) == 0) {
        if (!params->copy_stat) {
          fprintf(stderr, "argument --no-copy-stat / -n already set\n");
          return COMMAND_INVALID;
        }
        params->copy_stat = 0;
      } else if (strcmp("rm", arg) == 0) {
        if (keep_set) {
          fprintf(stderr, "argument --rm / -j or --keep / -k already set\n");
          return COMMAND_INVALID;
        }
        keep_set = 1;
        params->junk_source = 1;
      } else if (strcmp("squash", arg) == 0) {
        if (params->reject_uncompressible) {
          fprintf(stderr, "argument --squash / -s already set\n");
          return COMMAND_INVALID;
        }
        params->reject_uncompressible = 1;
      } else if (strcmp("stdout", arg) == 0) {
        if (params->write_to_stdout) {
          fprintf(stderr, "write to standard output already set\n");
          return COMMAND_INVALID;
        }
        params->write_to_stdout = 1;
      } else if (strcmp("test", arg) == 0) {
        if (command_set || command != COMMAND_COMPRESS) {
          fprintf(stderr, "command already set when parsing --test\n");
          return COMMAND_INVALID;
        }
        command_set = 1;
        command = COMMAND_TEST_INTEGRITY;
      } else if (strcmp("verbose", arg) == 0) {
        if (params->verbosity > 0) {
          fprintf(stderr, "argument --verbose / -v already set\n");
          return COMMAND_INVALID;
        }
        params->verbosity = 1;
      } else if (strcmp("version", arg) == 0) {
        return COMMAND_VERSION;
      } else if (strcmp("concatenated", arg) == 0) {
        if (params->allow_concatenated) {
          fprintf(stderr, "argument -K / --concatenated already set\n");
          return COMMAND_INVALID;
        }
        params->allow_concatenated = 1;
      } else {
        /* key=value */
        const char* value = strrchr(arg, '=');
        size_t key_len;
        if (!value || value[1] == 0) {
          fprintf(stderr, "must pass the parameter as --%s=value\n", arg);
          return COMMAND_INVALID;
        }
        key_len = (size_t)(value - arg);
        value++;
        if (strncmp("comment", arg, key_len) == 0) {
          if (comment_set) {
            fprintf(stderr, "comment already set\n");
            return COMMAND_INVALID;
          }
          comment_set = 1;
          if (!ParseBase64(value, params->comment, &params->comment_len)) {
            fprintf(stderr, "invalid base64-encoded comment\n");
            return COMMAND_INVALID;
          }
        } else if (strncmp("lgwin", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, BR_MAX_WINDOW_BITS, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < BR_MIN_WINDOW_BITS) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, BR_MIN_WINDOW_BITS);
            return COMMAND_INVALID;
          }
        } else if (strncmp("large_window", arg, key_len) == 0) {
          if (lgwin_set) {
            fprintf(stderr, "lgwin parameter already set\n");
            return COMMAND_INVALID;
          }
          lgwin_set = ParseInt(value, 0, BR_LARGE_MAX_WINDOW_BITS, &params->lgwin);
          if (!lgwin_set) {
            fprintf(stderr, "error parsing lgwin value [%s]\n", value);
            return COMMAND_INVALID;
          }
          if (params->lgwin != 0 && params->lgwin < BR_MIN_WINDOW_BITS) {
            fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (%d)\n", params->lgwin, BR_MIN_WINDOW_BITS);
            return COMMAND_INVALID;
          }
        } else if (strncmp("output", arg, key_len) == 0) {
          if (params->write_to_stdout) {
            fprintf(stderr, "write to standard output already set (-o)\n");
            return COMMAND_INVALID;
          }
          output_set = 1;
          params->output_path = value;
        } else if (strncmp("quality", arg, key_len) == 0) {
          if (quality_set) {
            fprintf(stderr, "quality already set\n");
            return COMMAND_INVALID;
          }
          quality_set = ParseInt(value, 0, 11, &params->quality);
          if (!quality_set) {
            fprintf(stderr, "error parsing quality value [%s]\n", value);
            return COMMAND_INVALID;
          }
        } else if (strncmp("suffix", arg, key_len) == 0) {
          if (suffix_set) {
            fprintf(stderr, "suffix already set\n");
            return COMMAND_INVALID;
          }
          suffix_set = 1;
          params->suffix = value;
        } else if (strncmp("dictionary", arg, key_len) == 0) {
          if (params->dictionary_path) {
            fprintf(stderr, "dictionary path already set\n");
            return COMMAND_INVALID;
          }
          params->dictionary_path = value;
        } else {
          fprintf(stderr, "invalid parameter: [%s]\n", arg);
          return COMMAND_INVALID;
        }
      }
    }
  }
  (void)output_set;
  (void)alias_stdout;
  (void)alias_concat;

  params->input_count = input_count;
  params->decompress = (command == COMMAND_DECOMPRESS);
  params->test_integrity = (command == COMMAND_TEST_INTEGRITY);

  /* Consistency checks (observed to fail silently). */
  if (params->write_to_stdout && input_count > 1) return COMMAND_INVALID;
  if (params->allow_concatenated && command != COMMAND_DECOMPRESS) return COMMAND_INVALID;
  if (params->allow_concatenated && params->comment_len > 0) return COMMAND_INVALID;
  if (params->reject_uncompressible && params->write_to_stdout) return COMMAND_INVALID;
  if (command == COMMAND_TEST_INTEGRITY && (params->write_to_stdout || params->output_path)) return COMMAND_INVALID;
  return command;
}

static int64_t FileSize(const char* path) {
  FILE* f = fopen(path, "rb");
  int64_t retval;
  if (f == NULL) return -1;
  if (fseek(f, 0L, SEEK_END) != 0) {
    fclose(f);
    return -1;
  }
  retval = ftell(f);
  if (fclose(f) != 0) return -1;
  return retval;
}

static void CopyStat(const char* input_path, const char* output_path) {
  struct stat statbuf;
  struct utimbuf times;
  int res;
  if (input_path == 0 || output_path == 0) return;
  if (stat(input_path, &statbuf) != 0) return;
  times.actime = statbuf.st_atime;
  times.modtime = statbuf.st_mtime;
  utime(output_path, &times);
  res = chmod(output_path, statbuf.st_mode & (S_IRWXU | S_IRWXG | S_IRWXO));
  if (res != 0) {
    fprintf(stderr, "setting access bits failed for [%s]: %s\n", output_path, strerror(errno));
  }
  res = chown(output_path, (uid_t)-1, statbuf.st_gid);
  if (res != 0) {
    fprintf(stderr, "setting group failed for [%s]: %s\n", output_path, strerror(errno));
  }
  res = chown(output_path, statbuf.st_uid, (gid_t)-1);
  if (res != 0) {
    fprintf(stderr, "setting user failed for [%s]: %s\n", output_path, strerror(errno));
  }
}

static int NextFile(Context* context) {
  const char* arg;
  size_t arg_len;

  context->iterator++;

  if (context->input_count == 0) {
    if (context->iterator > 1) return 0;
    context->current_input_path = NULL;
    context->input_file_length = -1;
    context->current_output_path = context->output_path;
    return 1;
  }

  while (context->iterator == context->not_input_indices[context->ignore]) {
    context->iterator++;
    context->ignore++;
  }

  if (context->iterator >= context->argc) return 0;

  arg = context->argv[context->iterator];
  arg_len = strlen(arg);
  if (arg_len == 1 && arg[0] == '-') {
    context->current_input_path = NULL;
    context->input_file_length = -1;
    context->current_output_path = context->output_path;
    return 1;
  }

  context->current_input_path = arg;
  context->input_file_length = FileSize(arg);
  context->current_output_path = context->output_path;

  if (context->output_path) return 1;
  if (context->write_to_stdout) return 1;

  strcpy(context->modified_path, arg);
  context->current_output_path = context->modified_path;
  if (context->decompress) {
    size_t suffix_len = strlen(context->suffix);
    char* name = (char*)FileName(context->modified_path);
    size_t name_len = strlen(name);
    char* name_end;
    if (name_len <= suffix_len) {
      fprintf(stderr, "empty output file name for [%s] input file\n", arg);
      context->iterator_error = 1;
      return 0;
    }
    name_end = name + name_len - suffix_len;
    if (strcmp(name_end, context->suffix) != 0) {
      fprintf(stderr, "input file [%s] suffix mismatch\n", arg);
      context->iterator_error = 1;
      return 0;
    }
    name_end[0] = 0;
    return 1;
  } else {
    strcpy(context->modified_path + arg_len, context->suffix);
    return 1;
  }
}

static int OpenInputFile(const char* input_path, FILE** f) {
  *f = NULL;
  if (!input_path) {
    *f = fdopen(STDIN_FILENO, "rb");
    return 1;
  }
  *f = fopen(input_path, "rb");
  if (!*f) {
    fprintf(stderr, "failed to open input file [%s]: %s\n", PrintablePath(input_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int OpenOutputFile(const char* output_path, FILE** f, int force) {
  int fd;
  *f = NULL;
  if (!output_path) {
    *f = fdopen(STDOUT_FILENO, "wb");
    return 1;
  }
  fd = open(output_path, O_CREAT | (force ? 0 : O_EXCL) | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
  if (fd < 0) {
    fprintf(stderr, "failed to open output file [%s]: %s\n", PrintablePath(output_path), strerror(errno));
    return 0;
  }
  *f = fdopen(fd, "wb");
  if (!*f) {
    fprintf(stderr, "failed to open output file [%s]: %s\n", PrintablePath(output_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int OpenFiles(Context* context) {
  int is_ok = OpenInputFile(context->current_input_path, &context->fin);
  if (!context->test_integrity && is_ok) {
    is_ok = OpenOutputFile(context->current_output_path, &context->fout, context->force_overwrite);
  }
  return is_ok;
}

static int CloseFiles(Context* context, int success) {
  int is_ok = 1;
  if (!context->test_integrity && context->fout) {
    if (!success && context->current_output_path) {
      unlink(context->current_output_path);
    }
    if (fclose(context->fout) != 0) {
      if (success) {
        fprintf(stderr, "fclose failed [%s]: %s\n", PrintablePath(context->current_output_path), strerror(errno));
      }
      is_ok = 0;
    }
    if (success && is_ok && context->copy_stat) {
      CopyStat(context->current_input_path, context->current_output_path);
    }
  }

  if (context->fin) {
    if (fclose(context->fin) != 0) {
      if (is_ok) {
        fprintf(stderr, "fclose failed [%s]: %s\n", PrintablePath(context->current_input_path), strerror(errno));
      }
      is_ok = 0;
    }
  }
  if (success && context->junk_source && context->current_input_path) {
    unlink(context->current_input_path);
  }

  context->fin = NULL;
  context->fout = NULL;
  return is_ok;
}

static void InitializeBuffers(Context* context) {
  context->available_in = 0;
  context->next_in = NULL;
  context->available_out = kFileBufferSize;
  context->next_out = context->output;
  context->total_in = 0;
  context->total_out = 0;
  if (context->verbosity > 0) {
    context->start_time = clock();
  }
}

static int HasMoreInput(Context* context) {
  return feof(context->fin) ? 0 : 1;
}

static int ProvideInput(Context* context) {
  context->available_in = fread(context->input, 1, kFileBufferSize, context->fin);
  context->total_in += context->available_in;
  context->next_in = context->input;
  if (ferror(context->fin)) {
    fprintf(stderr, "failed to read input [%s]: %s\n", PrintablePath(context->current_input_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int WriteOutput(Context* context) {
  size_t out_size = (size_t)(context->next_out - context->output);
  context->total_out += out_size;
  if (out_size == 0) return 1;
  if (context->test_integrity) return 1;

  fwrite(context->output, 1, out_size, context->fout);
  if (ferror(context->fout)) {
    fprintf(stderr, "failed to write output [%s]: %s\n", PrintablePath(context->current_output_path), strerror(errno));
    return 0;
  }
  return 1;
}

static int ProvideOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = kFileBufferSize;
  context->next_out = context->output;
  return 1;
}

static int FlushOutput(Context* context) {
  if (!WriteOutput(context)) return 0;
  context->available_out = 0;
  return 1;
}

static void PrintBytes(size_t value) {
  if (value < 1024) {
    fprintf(stderr, "%d B", (int)value);
  } else if (value < 1048576) {
    fprintf(stderr, "%0.3f KiB", (double)value / 1024.0);
  } else if (value < 1073741824) {
    fprintf(stderr, "%0.3f MiB", (double)value / 1048576.0);
  } else {
    fprintf(stderr, "%0.3f GiB", (double)value / 1073741824.0);
  }
}

static void PrintFileProcessingProgress(Context* context) {
  fprintf(stderr, "[%s]: ", PrintablePath(context->current_input_path));
  PrintBytes(context->total_in);
  fprintf(stderr, " -> ");
  PrintBytes(context->total_out);
  fprintf(stderr, " in %1.2f sec", (double)(context->end_time - context->start_time) / CLOCKS_PER_SEC);
}

/* ---------------- decompression ---------------- */

static size_t DecoderRead(void* opaque, const uint8_t** buf) {
  Context* context = (Context*)opaque;
  if (!HasMoreInput(context)) { context->decoder_eof = 1; return 0; }
  if (!ProvideInput(context)) { context->read_error = 1; return 0; }
  *buf = context->next_in;
  return context->available_in;
}

/* Emulates the decoder writing into the CLI's output buffer: flush when full and more pending. */
static int DecoderWrite(void* opaque, const uint8_t* data, size_t len) {
  Context* context = (Context*)opaque;
  while (len > 0) {
    size_t n;
    if (context->available_out == 0) {
      if (!ProvideOutput(context)) { context->write_error = 1; return 0; }
    }
    n = BR_MIN(len, context->available_out);
    memcpy(context->next_out, data, n);
    context->next_out += n;
    context->available_out -= n;
    data += n;
    len -= n;
  }
  return 1;
}

static int DecoderMetaStart(void* opaque, size_t size) {
  Context* context = (Context*)opaque;
  if (context->comment_len == 0) return 1;
  if (context->comment_state != 0) return 1;  /* only first metadata block is checked */
  context->comment_state = 1;
  context->comment_pos = 0;
  if (size != context->comment_len) { context->comment_state = -1; return 0; }
  return 1;
}

static int DecoderMetaChunk(void* opaque, const uint8_t* data, size_t len) {
  Context* context = (Context*)opaque;
  size_t i;
  if (context->comment_state != 1) return 1;
  for (i = 0; i < len; i++) {
    if (context->comment_pos >= context->comment_len || data[i] != context->comment[context->comment_pos]) {
      context->comment_state = -1;
      return 0;
    }
    context->comment_pos++;
  }
  return 1;
}

static int DecoderMetaEnd(void* opaque) {
  Context* context = (Context*)opaque;
  if (context->comment_state == 1) {
    if (context->comment_pos != context->comment_len) { context->comment_state = -1; return 0; }
    context->comment_state = 2;
  }
  return 1;
}

static int DecompressFile(Context* context) {
  BrDecoderIO io;
  BrDecoderStatus status;
  int first = 1;
  InitializeBuffers(context);
  context->read_error = 0;
  context->write_error = 0;
  context->comment_state = 0;
  context->decoder_eof = 0;
  memset(&io, 0, sizeof(io));
  io.read = DecoderRead;
  io.write = DecoderWrite;
  io.meta_start = DecoderMetaStart;
  io.meta_chunk = DecoderMetaChunk;
  io.meta_end = DecoderMetaEnd;
  io.opaque = context;
  io.custom_dict = context->dictionary;
  io.custom_dict_size = context->dictionary_size;
  for (;;) {
    /* Pre-provide input remaining from the previous stream, if any. */
    (void)first;
    br_decode_stream_ex(&io, &status, context->available_in ? context->next_in : NULL, context->available_in);
    context->next_in = status.rest;
    context->available_in = status.rest_len;
    if (status.result == BR_DEC_SUCCESS) {
      int has_more_input;
      if (!FlushOutput(context)) return 0;
      if (context->available_in == 0 && HasMoreInput(context)) {
        if (!ProvideInput(context)) return 0;
      }
      has_more_input = context->available_in != 0;
      if (has_more_input) {
        if (context->allow_concatenated) {
          if (context->verbosity > 0) fprintf(stderr, "extra input\n");
          context->available_out = kFileBufferSize;
          context->next_out = context->output;
          first = 0;
          continue;
        }
        fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
        if (context->verbosity > 0) fprintf(stderr, "reason: extra input\n");
        return 0;
      }
      if (context->verbosity > 0) {
        context->end_time = clock();
        fprintf(stderr, "Decompressed ");
        PrintFileProcessingProgress(context);
        fprintf(stderr, "\n");
      }
      if (context->comment_len > 0 && context->comment_state == 0) {
        fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
        if (context->verbosity > 0) fprintf(stderr, "reason: comment mismatch\n");
      }
      return 1;
    } else if (status.result == BR_DEC_NEEDS_MORE_INPUT) {
      if (context->read_error) return 0;
      fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
      if (context->verbosity > 0) fprintf(stderr, "reason: truncated input\n");
      return 0;
    } else if (status.result == BR_DEC_ABORT_OUTPUT) {
      return 0;
    } else if (status.result == BR_DEC_ABORT_METADATA) {
      fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
      if (context->verbosity > 0) fprintf(stderr, "reason: comment mismatch\n");
      return 0;
    } else {
      fprintf(stderr, "corrupt input [%s]\n", PrintablePath(context->current_input_path));
      if (context->verbosity > 0) {
        fprintf(stderr, "reason: %s (%d)\n", br_decoder_error_string(status.result), status.result);
      }
      return 0;
    }
  }
}

static int DecompressFiles(Context* context) {
  while (NextFile(context)) {
    int is_ok = 1;
    is_ok = OpenFiles(context);
    if (is_ok) is_ok = DecompressFile(context);
    if (!CloseFiles(context, is_ok)) is_ok = 0;
    if (!is_ok) return 0;
  }
  return 1;
}

/* ---------------- compression ---------------- */

static int CompressFile(Context* context, BrEncoder* s) {
  int is_eof = 0;
  InitializeBuffers(context);
  if (context->comment_len > 0) {
    size_t comment_in = context->comment_len;
    const uint8_t* comment_ptr = context->comment;
    br_encoder_emit_metadata(s, &comment_in, &comment_ptr, &context->available_out, &context->next_out);
  }
  for (;;) {
    if (context->available_in == 0 && !is_eof) {
      if (!ProvideInput(context)) return 0;
      is_eof = !HasMoreInput(context);
    }

    if (!br_encoder_compress_stream(s, is_eof ? BR_OP_FINISH : BR_OP_PROCESS,
        &context->available_in, &context->next_in, &context->available_out, &context->next_out)) {
      fprintf(stderr, "failed to compress data [%s]\n", PrintablePath(context->current_input_path));
      return 0;
    }

    if (context->available_out == 0) {
      if (!ProvideOutput(context)) return 0;
    }

    if (br_encoder_is_finished(s)) {
      if (!FlushOutput(context)) return 0;
      if (context->verbosity > 0) {
        context->end_time = clock();
        fprintf(stderr, "Compressed ");
        PrintFileProcessingProgress(context);
        fprintf(stderr, "\n");
      }
      return 1;
    }
  }
}

static int CompressFiles(Context* context) {
  while (NextFile(context)) {
    int is_ok = 1;
    int rejected = 0;
    BrEncoder* s = br_encoder_create();
    if (!s) {
      fprintf(stderr, "out of memory\n");
      return 0;
    }
    br_encoder_set_quality(s, context->quality);
    if (context->lgwin > 0) {
      if (context->lgwin > BR_MAX_WINDOW_BITS) {
        br_encoder_set_large_window(s, 1);
      }
      br_encoder_set_lgwin(s, context->lgwin);
    } else {
      uint32_t lgwin = DEFAULT_LGWIN;
      if (context->input_file_length >= 0) {
        lgwin = BR_MIN_WINDOW_BITS;
        while (BR_MAX_BACKWARD_LIMIT(lgwin) < (uint64_t)context->input_file_length) {
          lgwin++;
          if (lgwin == BR_MAX_WINDOW_BITS) break;
        }
      }
      br_encoder_set_lgwin(s, (int)lgwin);
    }
    if (context->input_file_length > 0) {
      uint32_t size_hint = context->input_file_length < (1 << 30) ? (uint32_t)context->input_file_length : (1u << 30);
      br_encoder_set_size_hint(s, size_hint);
    }
    if (context->prepared_dictionary) {
      br_encoder_attach_dictionary(s, context->prepared_dictionary);
    }
    is_ok = OpenFiles(context);
    if (is_ok && !context->current_output_path && !context->force_overwrite && isatty(STDOUT_FILENO)) {
      fprintf(stderr, "Use -h help. Use -f to force output to a terminal.\n");
      is_ok = 0;
    }
    if (is_ok) is_ok = CompressFile(context, s);
    br_encoder_destroy(s);
    if (is_ok && context->reject_uncompressible && context->total_out > context->total_in) {
      rejected = 1;
      if (context->verbosity > 0) fprintf(stderr, "Output is larger than input\n");
    }
    if (rejected) {
      /* Remove destination, keep source. */
      int junk = context->junk_source;
      context->junk_source = 0;
      if (!CloseFiles(context, 1)) is_ok = 0;
      context->junk_source = junk;
      if (context->current_output_path) unlink(context->current_output_path);
    } else {
      if (!CloseFiles(context, is_ok)) is_ok = 0;
    }
    if (!is_ok) return 0;
  }
  return 1;
}

static int ReadDictionary(Context* context, Command command) {
  static const int kMaxDictionarySize = 50331660;
  FILE* f;
  int64_t file_size_64;
  uint8_t* buffer;
  size_t bytes_read;

  if (context->dictionary_path == NULL) return 1;
  f = fopen(context->dictionary_path, "rb");
  if (f == NULL) {
    fprintf(stderr, "failed to open dictionary file [%s]: %s\n", PrintablePath(context->dictionary_path), strerror(errno));
    return 0;
  }

  file_size_64 = FileSize(context->dictionary_path);
  if (file_size_64 == -1) {
    fprintf(stderr, "could not get size of dictionary file [%s]", PrintablePath(context->dictionary_path));
    fclose(f);
    return 0;
  }

  if (file_size_64 > kMaxDictionarySize) {
    fprintf(stderr, "dictionary [%s] is larger than maximum allowed: %d\n", PrintablePath(context->dictionary_path), kMaxDictionarySize);
    fclose(f);
    return 0;
  }
  context->dictionary_size = (size_t)file_size_64;

  buffer = (uint8_t*)malloc(context->dictionary_size + 1);
  if (!buffer) {
    fprintf(stderr, "could not read dictionary: out of memory\n");
    fclose(f);
    return 0;
  }
  bytes_read = fread(buffer, sizeof(uint8_t), context->dictionary_size, f);
  if (bytes_read != context->dictionary_size) {
    free(buffer);
    fprintf(stderr, "failed to read dictionary [%s]: %s\n", PrintablePath(context->dictionary_path), strerror(errno));
    fclose(f);
    return 0;
  }
  fclose(f);
  context->dictionary = buffer;

  if (command == COMMAND_COMPRESS) {
    context->prepared_dictionary = br_encoder_prepare_dictionary(context->dictionary, context->dictionary_size, 11);
    if (context->prepared_dictionary == NULL) {
      fprintf(stderr, "failed to prepare dictionary [%s]\n", PrintablePath(context->dictionary_path));
      return 0;
    }
  }
  return 1;
}

int main(int argc, char** argv) {
  Command command;
  Context context;
  int is_ok = 1;
  int i;

  br_init_cmd_lut();

  memset(&context, 0, sizeof(context));
  context.quality = 11;
  context.lgwin = -1;
  context.verbosity = 0;
  context.force_overwrite = 0;
  context.junk_source = 0;
  context.reject_uncompressible = 0;
  context.copy_stat = 1;
  context.test_integrity = 0;
  context.write_to_stdout = 0;
  context.decompress = 0;
  context.large_window = 0;
  context.allow_concatenated = 0;
  context.output_path = NULL;
  context.dictionary_path = NULL;
  context.suffix = DEFAULT_SUFFIX;
  context.comment_len = 0;
  for (i = 0; i < MAX_OPTIONS; ++i) context.not_input_indices[i] = 0;
  context.longest_path_len = 1;
  context.input_count = 0;

  context.argc = argc;
  context.argv = argv;
  context.dictionary = NULL;
  context.dictionary_size = 0;
  context.prepared_dictionary = NULL;
  context.modified_path = NULL;
  context.iterator = 0;
  context.ignore = 0;
  context.iterator_error = 0;
  context.buffer = NULL;
  context.current_input_path = NULL;
  context.current_output_path = NULL;
  context.fin = NULL;
  context.fout = NULL;

  command = ParseParams(&context);

  if (command == COMMAND_COMPRESS || command == COMMAND_DECOMPRESS || command == COMMAND_TEST_INTEGRITY) {
    if (is_ok && context.dictionary_path) is_ok = ReadDictionary(&context, command);
    if (is_ok) {
      size_t modified_path_len = context.longest_path_len + strlen(context.suffix) + 1;
      context.modified_path = (char*)malloc(modified_path_len);
      context.buffer = (uint8_t*)malloc(kFileBufferSize * 2);
      if (!context.modified_path || !context.buffer) {
        fprintf(stderr, "out of memory\n");
        is_ok = 0;
      } else {
        context.input = context.buffer;
        context.output = context.buffer + kFileBufferSize;
      }
    }
  }

  if (!is_ok) command = COMMAND_NOOP;

  switch (command) {
    case COMMAND_NOOP:
      break;
    case COMMAND_VERSION:
      PrintVersion();
      break;
    case COMMAND_COMPRESS:
      is_ok = CompressFiles(&context);
      break;
    case COMMAND_DECOMPRESS:
    case COMMAND_TEST_INTEGRITY:
      is_ok = DecompressFiles(&context);
      break;
    case COMMAND_HELP:
    case COMMAND_INVALID:
    default:
      is_ok = (command == COMMAND_HELP);
      PrintHelp(FileName(argv[0]), !is_ok);
      break;
  }

  if (context.iterator_error) is_ok = 0;

  br_encoder_destroy_prepared_dictionary(context.prepared_dictionary);
  free(context.dictionary);
  free(context.modified_path);
  free(context.buffer);

  if (!is_ok) exit(1);
  return 0;
}
