#ifndef BR_COMMAND_H
#define BR_COMMAND_H
#include "../common/platform.h"
#include "../common/prefix.h"
#include "fast_log.h"
#include "params.h"

typedef struct Command {
  uint32_t insert_len_;
  /* copy_len in low 25 bits, copy_code - copy_len in high 7 bits. */
  uint32_t copy_len_;
  uint32_t dist_extra_;
  uint16_t cmd_prefix_;
  /* distance code in low 10 bits, number of extra bits in high 6 bits. */
  uint16_t dist_prefix_;
} Command;

static inline uint16_t get_insert_length_code(size_t insertlen) {
  if (insertlen < 6) {
    return (uint16_t)insertlen;
  } else if (insertlen < 130) {
    uint32_t nbits = br_log2_floor_nonzero(insertlen - 2) - 1u;
    return (uint16_t)((nbits << 1) + ((insertlen - 2) >> nbits) + 2);
  } else if (insertlen < 2114) {
    return (uint16_t)(br_log2_floor_nonzero(insertlen - 66) + 10);
  } else if (insertlen < 6210) {
    return 21u;
  } else if (insertlen < 22594) {
    return 22u;
  } else {
    return 23u;
  }
}

static inline uint16_t get_copy_length_code(size_t copylen) {
  if (copylen < 10) {
    return (uint16_t)(copylen - 2);
  } else if (copylen < 134) {
    uint32_t nbits = br_log2_floor_nonzero(copylen - 6) - 1u;
    return (uint16_t)((nbits << 1) + ((copylen - 6) >> nbits) + 4);
  } else if (copylen < 2118) {
    return (uint16_t)(br_log2_floor_nonzero(copylen - 70) + 12);
  } else {
    return 23u;
  }
}

static inline uint16_t combine_length_codes(uint16_t inscode, uint16_t copycode, int use_last_distance) {
  uint16_t bits64 = (uint16_t)((copycode & 0x7u) | ((inscode & 0x7u) << 3u));
  if (use_last_distance && inscode < 8u && copycode < 16u) {
    return (copycode < 8u) ? bits64 : (uint16_t)(bits64 | 64u);
  } else {
    uint32_t offset = 2u * ((copycode >> 3u) + 3u * (inscode >> 3u));
    offset = (offset << 5u) + 0x40u + ((0x520D40u >> offset) & 0xC0u);
    return (uint16_t)(offset | bits64);
  }
}

static inline void get_length_code(size_t insertlen, size_t copylen, int use_last_distance, uint16_t* code) {
  uint16_t inscode = get_insert_length_code(insertlen);
  uint16_t copycode = get_copy_length_code(copylen);
  *code = combine_length_codes(inscode, copycode, use_last_distance);
}

static inline uint32_t get_insert_base(uint16_t inscode) { return kInsBase[inscode]; }
static inline uint32_t get_insert_extra(uint16_t inscode) { return kInsExtra[inscode]; }
static inline uint32_t get_copy_base(uint16_t copycode) { return kCopyBase[copycode]; }
static inline uint32_t get_copy_extra(uint16_t copycode) { return kCopyExtra[copycode]; }

static inline void prefix_encode_copy_distance(size_t distance_code, size_t num_direct_codes, size_t postfix_bits, uint16_t* code, uint32_t* extra_bits) {
  if (distance_code < BR_NUM_DISTANCE_SHORT_CODES + num_direct_codes) {
    *code = (uint16_t)distance_code;
    *extra_bits = 0;
    return;
  } else {
    size_t dist = ((size_t)1 << (postfix_bits + 2u)) + (distance_code - BR_NUM_DISTANCE_SHORT_CODES - num_direct_codes);
    size_t bucket = br_log2_floor_nonzero(dist) - 1;
    size_t postfix_mask = (1u << postfix_bits) - 1;
    size_t postfix = dist & postfix_mask;
    size_t prefix = (dist >> bucket) & 1;
    size_t offset = (2 + prefix) << bucket;
    size_t nbits = bucket - postfix_bits;
    *code = (uint16_t)((nbits << 10) | (BR_NUM_DISTANCE_SHORT_CODES + num_direct_codes + ((2 * (nbits - 1) + prefix) << postfix_bits) + postfix));
    *extra_bits = (uint32_t)((dist - offset) >> postfix_bits);
  }
}

static inline void init_command(Command* self, const BrDistanceParams* dist, size_t insertlen, size_t copylen, int copylen_code_delta, size_t distance_code) {
  uint32_t delta = (uint8_t)((int8_t)copylen_code_delta);
  self->insert_len_ = (uint32_t)insertlen;
  self->copy_len_ = (uint32_t)(copylen | (delta << 25));
  prefix_encode_copy_distance(distance_code, dist->num_direct_distance_codes, dist->distance_postfix_bits, &self->dist_prefix_, &self->dist_extra_);
  get_length_code(insertlen, (size_t)((int)copylen + copylen_code_delta), (self->dist_prefix_ & 0x3FF) == 0, &self->cmd_prefix_);
}

static inline void init_insert_command(Command* self, size_t insertlen) {
  self->insert_len_ = (uint32_t)insertlen;
  self->copy_len_ = 4 << 25;
  self->dist_extra_ = 0;
  self->dist_prefix_ = BR_NUM_DISTANCE_SHORT_CODES;
  get_length_code(insertlen, 4, 0, &self->cmd_prefix_);
}

static inline uint32_t command_restore_distance_code(const Command* self, const BrDistanceParams* dist) {
  if ((self->dist_prefix_ & 0x3FFu) < BR_NUM_DISTANCE_SHORT_CODES + dist->num_direct_distance_codes) {
    return self->dist_prefix_ & 0x3FFu;
  } else {
    uint32_t dcode = self->dist_prefix_ & 0x3FFu;
    uint32_t nbits = self->dist_prefix_ >> 10;
    uint32_t extra = self->dist_extra_;
    uint32_t postfix_mask = (1U << dist->distance_postfix_bits) - 1U;
    uint32_t hcode = (dcode - dist->num_direct_distance_codes - BR_NUM_DISTANCE_SHORT_CODES) >> dist->distance_postfix_bits;
    uint32_t lcode = (dcode - dist->num_direct_distance_codes - BR_NUM_DISTANCE_SHORT_CODES) & postfix_mask;
    uint32_t offset = ((2U + (hcode & 1U)) << nbits) - 4U;
    return ((offset + extra) << dist->distance_postfix_bits) + lcode + dist->num_direct_distance_codes + BR_NUM_DISTANCE_SHORT_CODES;
  }
}

static inline uint32_t command_distance_context(const Command* self) {
  uint32_t r = self->cmd_prefix_ >> 6;
  uint32_t c = self->cmd_prefix_ & 7;
  if ((r == 0 || r == 2 || r == 4 || r == 7) && (c <= 2)) return c;
  return 3;
}

static inline uint32_t command_copy_len(const Command* self) { return self->copy_len_ & 0x1FFFFFF; }

static inline uint32_t command_copy_len_code(const Command* self) {
  uint32_t modifier = self->copy_len_ >> 25;
  int32_t delta = (int8_t)((uint8_t)(modifier | ((modifier & 0x40) << 1)));
  return (uint32_t)((int32_t)(self->copy_len_ & 0x1FFFFFF) + delta);
}
#endif
