cd /workspace/src/enc && cat > brotli_bit_stream.c <<'EOF'
/* Serialization of meta-blocks into the brotli bit stream. */
#include "brotli_bit_stream.h"
#include "write_bits.h"
#include "../common/context.h"

uint8_t kCodeLengthDepth[18];
uint16_t kCodeLengthBits[18];
uint8_t kZeroRepsDepth[BR_NUM_COMMAND_SYMBOLS];
uint64_t kZeroRepsBits[BR_NUM_COMMAND_SYMBOLS];
uint8_t kNonZeroRepsDepth[BR_NUM_COMMAND_SYMBOLS];
uint64_t kNonZeroRepsBits[BR_NUM_COMMAND_SYMBOLS];
uint8_t kStaticCommandCodeDepth[BR_NUM_COMMAND_SYMBOLS];
uint16_t kStaticCommandCodeBits[BR_NUM_COMMAND_SYMBOLS];
uint8_t kStaticDistanceCodeDepth[64];
uint16_t kStaticDistanceCodeBits[64];

/* Static code length code: symbols 0..12,16,17 have length 4; 13,14 have length 5; 15 unused. */
void br_init_static_tables(void) {
  static int initialized = 0;
  size_t i;
  if (initialized) return;
  initialized = 1;
  for (i = 0; i < 18; i++) kCodeLengthDepth[i] = 4;
  kCodeLengthDepth[13] = 5;
  kCodeLengthDepth[14] = 5;
  kCodeLengthDepth[15] = 0;
  br_convert_bit_depths_to_symbols(kCodeLengthDepth, 18, kCodeLengthBits);
  /* Repetition tables for zeros: reps zeros encoded with code-length code. */
  for (i = 0; i < BR_NUM_COMMAND_SYMBOLS; i++) {
    uint8_t tree[64], extra[64];
    size_t tree_size = 0, k;
    uint64_t bits = 0;
    size_t depth = 0;
    if (i == 0) { kZeroRepsDepth[0] = 0; kZeroRepsBits[0] = 0; }
    else {
      /* reproduce WriteHuffmanTreeRepetitionsZeros */
      size_t repetitions = i;
      if (repetitions == 11) { tree[tree_size] = 0; extra[tree_size] = 0; tree_size++; repetitions--; }
      if (repetitions < 3) {
        for (k = 0; k < repetitions; k++) { tree[tree_size] = 0; extra[tree_size] = 0; tree_size++; }
      } else {
        size_t start = tree_size;
        repetitions -= 3;
        for (;;) {
          tree[tree_size] = BR_REPEAT_ZERO_CODE_LENGTH;
          extra[tree_size] = (uint8_t)(repetitions & 0x7);
          tree_size++;
          repetitions >>= 3;
          if (repetitions == 0) break;
          --repetitions;
        }
        /* reverse */
        {
          size_t a = start, b = tree_size - 1;
          while (a < b) { uint8_t t = tree[a]; tree[a] = tree[b]; tree[b] = t; t = extra[a]; extra[a] = extra[b]; extra[b] = t; a++; b--; }
        }
      }
      for (k = 0; k < tree_size; k++) {
        bits |= (uint64_t)kCodeLengthBits[tree[k]] << depth;
        depth += kCodeLengthDepth[tree[k]];
        if (tree[k] == BR_REPEAT_ZERO_CODE_LENGTH) { bits |= (uint64_t)extra[k] << depth; depth += 3; }
      }
      kZeroRepsDepth[i] = (uint8_t)depth;
      kZeroRepsBits[i] = bits;
    }
  }
  /* Non-zero repetitions: index = reps - 3 (reps >= 3) encoded with code 16 chain. */
  for (i = 0; i < BR_NUM_COMMAND_SYMBOLS; i++) {
    uint8_t tree[64], extra[64];
    size_t tree_size = 0, k;
    uint64_t bits = 0;
    size_t depth = 0;
    size_t repetitions = i;
    for (;;) {
      tree[tree_size] = BR_REPEAT_PREVIOUS_CODE_LENGTH;
      extra[tree_size] = (uint8_t)(repetitions & 0x3);
      tree_size++;
      repetitions >>= 2;
      if (repetitions == 0) break;
      --repetitions;
    }
    {
      size_t a = 0, b = tree_size - 1;
      while (a < b) { uint8_t t = tree[a]; tree[a] = tree[b]; tree[b] = t; t = extra[a]; extra[a] = extra[b]; extra[b] = t; a++; b--; }
    }
    for (k = 0; k < tree_size; k++) {
      bits |= (uint64_t)kCodeLengthBits[tree[k]] << depth;
      depth += kCodeLengthDepth[tree[k]];
      bits |= (uint64_t)extra[k] << depth;
      depth += 2;
    }
    kNonZeroRepsDepth[i] = (uint8_t)depth;
    kNonZeroRepsBits[i] = bits;
  }
  /* Static command and distance codes. */
  for (i = 0; i < BR_NUM_COMMAND_SYMBOLS; i++) kStaticCommandCodeDepth[i] = (uint8_t)(i < 448 ? 9 : 11);
  br_convert_bit_depths_to_symbols(kStaticCommandCodeDepth, BR_NUM_COMMAND_SYMBOLS, kStaticCommandCodeBits);
  for (i = 0; i < 64; i++) kStaticDistanceCodeDepth[i] = 6;
  br_convert_bit_depths_to_symbols(kStaticDistanceCodeDepth, 64, kStaticDistanceCodeBits);
}

static inline uint32_t block_length_prefix_code(uint32_t len) {
  uint32_t code = (len >= 177) ? (len >= 753 ? 20 : 14) : (len >= 41 ? 7 : 0);
  while (code < (BR_NUM_BLOCK_LEN_SYMBOLS - 1) && len >= kBlockLengthPrefixCode[code + 1].offset) ++code;
  return code;
}

static inline void get_block_length_prefix_code(uint32_t len, size_t* code, uint32_t* n_extra, uint32_t* extra) {
  *code = block_length_prefix_code(len);
  *n_extra = kBlockLengthPrefixCode[*code].nbits;
  *extra = len - kBlockLengthPrefixCode[*code].offset;
}

typedef struct { size_t last_type; size_t second_last_type; } BlockTypeCodeCalculator;

static void init_block_type_code_calculator(BlockTypeCodeCalculator* self) { self->last_type = 1; self->second_last_type = 0; }

static inline size_t next_block_type_code(BlockTypeCodeCalculator* calculator, uint8_t type) {
  size_t type_code = (type == calculator->last_type + 1) ? 1u : (type == calculator->second_last_type) ? 0u : type + 2u;
  calculator->second_last_type = calculator->last_type;
  calculator->last_type = type;
  return type_code;
}

static void encode_mlen(size_t length, uint64_t* bits, size_t* numbits, uint64_t* nibblesbits) {
  size_t lg = (length == 1) ? 1 : br_log2_floor_nonzero((uint32_t)(length - 1)) + 1;
  size_t mnibbles = (lg < 16 ? 16 : (lg + 3)) / 4;
  *nibblesbits = mnibbles - 4;
  *numbits = mnibbles * 4;
  *bits = length - 1;
}

static inline void store_command_extra(const Command* cmd, size_t* storage_ix, uint8_t* storage) {
  uint32_t copylen_code = command_copy_len_code(cmd);
  uint16_t inscode = get_insert_length_code(cmd->insert_len_);
  uint16_t copycode = get_copy_length_code(copylen_code);
  uint32_t insnumextra = get_insert_extra(inscode);
  uint64_t insextraval = cmd->insert_len_ - get_insert_base(inscode);
  uint64_t copyextraval = copylen_code - get_copy_base(copycode);
  uint64_t bits = (copyextraval << insnumextra) | insextraval;
  br_write_bits(insnumextra + get_copy_extra(copycode), bits, storage_ix, storage);
}

typedef struct {
  BlockTypeCodeCalculator type_code_calculator;
  uint8_t type_depths[BR_MAX_BLOCK_TYPE_SYMBOLS];
  uint16_t type_bits[BR_MAX_BLOCK_TYPE_SYMBOLS];
  uint8_t length_depths[BR_NUM_BLOCK_LEN_SYMBOLS];
  uint16_t length_bits[BR_NUM_BLOCK_LEN_SYMBOLS];
} BlockSplitCode;

static void store_var_len_uint8(size_t n, size_t* storage_ix, uint8_t* storage) {
  if (n == 0) {
    br_write_bits(1, 0, storage_ix, storage);
  } else {
    size_t nbits = br_log2_floor_nonzero(n);
    br_write_bits(1, 1, storage_ix, storage);
    br_write_bits(3, nbits, storage_ix, storage);
    br_write_bits(nbits, n - ((size_t)1 << nbits), storage_ix, storage);
  }
}

static void store_compressed_meta_block_header(int is_final_block, size_t length, size_t* storage_ix, uint8_t* storage) {
  uint64_t lenbits;
  size_t nlenbits;
  uint64_t nibblesbits;
  br_write_bits(1, (uint64_t)is_final_block, storage_ix, storage);
  if (is_final_block) br_write_bits(1, 0, storage_ix, storage);
  encode_mlen(length, &lenbits, &nlenbits, &nibblesbits);
  br_write_bits(2, nibblesbits, storage_ix, storage);
  br_write_bits(nlenbits, lenbits, storage_ix, storage);
  if (!is_final_block) br_write_bits(1, 0, storage_ix, storage);
}

static void store_uncompressed_meta_block_header(size_t length, size_t* storage_ix, uint8_t* storage) {
  uint64_t lenbits;
  size_t nlenbits;
  uint64_t nibblesbits;
  br_write_bits(1, 0, storage_ix, storage);
  encode_mlen(length, &lenbits, &nlenbits, &nibblesbits);
  br_write_bits(2, nibblesbits, storage_ix, storage);
  br_write_bits(nlenbits, lenbits, storage_ix, storage);
  br_write_bits(1, 1, storage_ix, storage);
}

void br_store_meta_block_header(size_t len, int is_uncompressed, size_t* storage_ix, uint8_t* storage) {
  uint64_t lenbits;
  size_t nlenbits;
  uint64_t nibblesbits;
  br_write_bits(1, 0, storage_ix, storage);  /* ISLAST */
  encode_mlen(len, &lenbits, &nlenbits, &nibblesbits);
  br_write_bits(2, nibblesbits, storage_ix, storage);
  br_write_bits(nlenbits, lenbits, storage_ix, storage);
  br_write_bits(1, (uint64_t)is_uncompressed, storage_ix, storage);
}

static void store_huffman_tree_of_huffman_tree_to_bit_mask(const int num_codes, const uint8_t* code_length_bitdepth, size_t* storage_ix, uint8_t* storage) {
  static const uint8_t kStorageOrder[BR_CODE_LENGTH_CODES] = {1, 2, 3, 4, 0, 5, 17, 6, 16, 7, 8, 9, 10, 11, 12, 13, 14, 15};
  static const uint8_t kHuffmanBitLengthHuffmanCodeSymbols[6] = {0, 7, 3, 2, 1, 15};
  static const uint8_t kHuffmanBitLengthHuffmanCodeBitLengths[6] = {2, 4, 3, 2, 2, 4};
  size_t skip_some = 0;
  size_t codes_to_store = BR_CODE_LENGTH_CODES;
  if (num_codes > 1) {
    for (; codes_to_store > 0; --codes_to_store) {
      if (code_length_bitdepth[kStorageOrder[codes_to_store - 1]] != 0) break;
    }
  }
  if (code_length_bitdepth[kStorageOrder[0]] == 0 && code_length_bitdepth[kStorageOrder[1]] == 0) {
    skip_some = 2;
    if (code_length_bitdepth[kStorageOrder[2]] == 0) skip_some = 3;
  }
  br_write_bits(2, skip_some, storage_ix, storage);
  {
    size_t i;
    for (i = skip_some; i < codes_to_store; ++i) {
      size_t l = code_length_bitdepth[kStorageOrder[i]];
      br_write_bits(kHuffmanBitLengthHuffmanCodeBitLengths[l], kHuffmanBitLengthHuffmanCodeSymbols[l], storage_ix, storage);
    }
  }
}

static void store_huffman_tree_to_bit_mask(const size_t huffman_tree_size, const uint8_t* huffman_tree, const uint8_t* huffman_tree_extra_bits, const uint8_t* code_length_bitdepth, const uint16_t* code_length_bitdepth_symbols, size_t* storage_ix, uint8_t* storage) {
  size_t i;
  for (i = 0; i < huffman_tree_size; ++i) {
    size_t ix = huffman_tree[i];
    br_write_bits(code_length_bitdepth[ix], code_length_bitdepth_symbols[ix], storage_ix, storage);
    switch (ix) {
      case BR_REPEAT_PREVIOUS_CODE_LENGTH: br_write_bits(2, huffman_tree_extra_bits[i], storage_ix, storage); break;
      case BR_REPEAT_ZERO_CODE_LENGTH: br_write_bits(3, huffman_tree_extra_bits[i], storage_ix, storage); break;
    }
  }
}

static void store_simple_huffman_tree(const uint8_t* depths, size_t symbols[4], size_t num_symbols, size_t max_bits, size_t* storage_ix, uint8_t* storage) {
  br_write_bits(2, 1, storage_ix, storage);
  br_write_bits(2, num_symbols - 1, storage_ix, storage);
  {
    size_t i;
    for (i = 0; i < num_symbols; i++) {
      size_t j;
      for (j = i + 1; j < num_symbols; j++) {
        if (depths[symbols[j]] < depths[symbols[i]]) { size_t t = symbols[j]; symbols[j] = symbols[i]; symbols[i] = t; }
      }
    }
  }
  if (num_symbols == 2) {
    br_write_bits(max_bits, symbols[0], storage_ix, storage);
    br_write_bits(max_bits, symbols[1], storage_ix, storage);
  } else if (num_symbols == 3) {
    br_write_bits(max_bits, symbols[0], storage_ix, storage);
    br_write_bits(max_bits, symbols[1], storage_ix, storage);
    br_write_bits(max_bits, symbols[2], storage_ix, storage);
  } else {
    br_write_bits(max_bits, symbols[0], storage_ix, storage);
    br_write_bits(max_bits, symbols[1], storage_ix, storage);
    br_write_bits(max_bits, symbols[2], storage_ix, storage);
    br_write_bits(max_bits, symbols[3], storage_ix, storage);
    br_write_bits(1, depths[symbols[0]] == 1 ? 1 : 0, storage_ix, storage);
  }
}

void br_store_huffman_tree(const uint8_t* depths, size_t num, HuffmanTree* tree, size_t* storage_ix, uint8_t* storage) {
  uint8_t huffman_tree[BR_NUM_COMMAND_SYMBOLS];
  uint8_t huffman_tree_extra_bits[BR_NUM_COMMAND_SYMBOLS];
  size_t huffman_tree_size = 0;
  uint8_t code_length_bitdepth[BR_CODE_LENGTH_CODES] = {0};
  uint16_t code_length_bitdepth_symbols[BR_CODE_LENGTH_CODES];
  uint32_t huffman_tree_histogram[BR_CODE_LENGTH_CODES] = {0};
  size_t i;
  int num_codes = 0;
  size_t code = 0;
  br_write_huffman_tree(depths, num, &huffman_tree_size, huffman_tree, huffman_tree_extra_bits);
  for (i = 0; i < huffman_tree_size; ++i) ++huffman_tree_histogram[huffman_tree[i]];
  for (i = 0; i < BR_CODE_LENGTH_CODES; ++i) {
    if (huffman_tree_histogram[i]) {
      if (num_codes == 0) { code = i; num_codes = 1; }
      else if (num_codes == 1) { num_codes = 2; break; }
    }
  }
  br_create_huffman_tree(huffman_tree_histogram, BR_CODE_LENGTH_CODES, 5, tree, code_length_bitdepth);
  br_convert_bit_depths_to_symbols(code_length_bitdepth, BR_CODE_LENGTH_CODES, code_length_bitdepth_symbols);
  store_huffman_tree_of_huffman_tree_to_bit_mask(num_codes, code_length_bitdepth, storage_ix, storage);
  if (num_codes == 1) code_length_bitdepth[code] = 0;
  store_huffman_tree_to_bit_mask(huffman_tree_size, huffman_tree, huffman_tree_extra_bits, code_length_bitdepth, code_length_bitdepth_symbols, storage_ix, storage);
}

void br_build_and_store_huffman_tree(const uint32_t* histogram, const size_t histogram_length, const size_t alphabet_size, HuffmanTree* tree, uint8_t* depth, uint16_t* bits, size_t* storage_ix, uint8_t* storage) {
  size_t count = 0;
  size_t s4[4] = {0};
  size_t i;
  size_t max_bits = 0;
  for (i = 0; i < histogram_length; i++) {
    if (histogram[i]) {
      if (count < 4) s4[count] = i;
      else if (count > 4) break;
      count++;
    }
  }
  {
    size_t max_bits_counter = alphabet_size - 1;
    while (max_bits_counter) { max_bits_counter >>= 1; ++max_bits; }
  }
  if (count <= 1) {
    br_write_bits(4, 1, storage_ix, storage);
    br_write_bits(max_bits, s4[0], storage_ix, storage);
    depth[s4[0]] = 0;
    bits[s4[0]] = 0;
    return;
  }
  memset(depth, 0, histogram_length * sizeof(depth[0]));
  br_create_huffman_tree(histogram, histogram_length, 15, tree, depth);
  br_convert_bit_depths_to_symbols(depth, histogram_length, bits);
  if (count <= 4) {
    store_simple_huffman_tree(depth, s4, count, max_bits, storage_ix, storage);
  } else {
    br_store_huffman_tree(depth, histogram_length, tree, storage_ix, storage);
  }
}

static inline void store_static_code_length_code(size_t* storage_ix, uint8_t* storage) {
  br_write_bits(40, 0x0000FF55555554ull, storage_ix, storage);
}

void br_build_and_store_huffman_tree_fast(HuffmanTree* tree, const uint32_t* histogram, const size_t histogram_total, const size_t max_bits, uint8_t* depth, uint16_t* bits, size_t* storage_ix, uint8_t* storage) {
  size_t count = 0;
  size_t symbols[4] = {0};
  size_t length = 0;
  size_t total = histogram_total;
  while (total != 0) {
    if (histogram[length]) {
      if (count < 4) symbols[count] = length;
      ++count;
      total -= histogram[length];
    }
    ++length;
  }
  if (count <= 1) {
    br_write_bits(4, 1, storage_ix, storage);
    br_write_bits(max_bits, symbols[0], storage_ix, storage);
    depth[symbols[0]] = 0;
    bits[symbols[0]] = 0;
    return;
  }
  memset(depth, 0, length * sizeof(depth[0]));
  {
    uint32_t count_limit;
    for (count_limit = 1;; count_limit *= 2) {
      HuffmanTree* node = tree;
      size_t l;
      for (l = length; l != 0;) {
        --l;
        if (histogram[l]) {
          if (histogram[l] >= count_limit) init_huffman_tree(node, histogram[l], -1, (int16_t)l);
          else init_huffman_tree(node, count_limit, -1, (int16_t)l);
          ++node;
        }
      }
      {
        const int n = (int)(node - tree);
        HuffmanTree sentinel;
        int i = 0;
        int j = n + 1;
        int k;
        /* sort */
        {
          int a;
          for (a = 1; a < n; a++) {
            HuffmanTree tmp = tree[a];
            int b = a - 1;
            while (b >= 0 && (tmp.total_count_ < tree[b].total_count_ || (tmp.total_count_ == tree[b].total_count_ && tmp.index_right_or_value_ > tree[b].index_right_or_value_))) {
              tree[b + 1] = tree[b];
              b--;
            }
            tree[b + 1] = tmp;
          }
        }
        init_huffman_tree(&sentinel, 0xFFFFFFFFu, -1, -1);
        *node++ = sentinel;
        for (k = n - 1; k > 0; --k) {
          int left, right;
          if (tree[i].total_count_ <= tree[j].total_count_) { left = i; ++i; } else { left = j; ++j; }
          if (tree[i].total_count_ <= tree[j].total_count_) { right = i; ++i; } else { right = j; ++j; }
          node[-1].total_count_ = tree[left].total_count_ + tree[right].total_count_;
          node[-1].index_left_ = (int16_t)left;
          node[-1].index_right_or_value_ = (int16_t)right;
          *node++ = sentinel;
        }
        if (br_set_depth(2 * n - 1, tree, depth, 14)) break;
      }
    }
  }
  br_convert_bit_depths_to_symbols(depth, length, bits);
  if (count <= 4) {
    size_t i;
    br_write_bits(2, 1, storage_ix, storage);
    br_write_bits(2, count - 1, storage_ix, storage);
    for (i = 0; i < count; i++) {
      size_t j;
      for (j = i + 1; j < count; j++) {
        if (depth[symbols[j]] < depth[symbols[i]]) { size_t t = symbols[j]; symbols[j] = symbols[i]; symbols[i] = t; }
      }
    }
    if (count == 2) {
      br_write_bits(max_bits, symbols[0], storage_ix, storage);
      br_write_bits(max_bits, symbols[1], storage_ix, storage);
    } else if (count == 3) {
      br_write_bits(max_bits, symbols[0], storage_ix, storage);
      br_write_bits(max_bits, symbols[1], storage_ix, storage);
      br_write_bits(max_bits, symbols[2], storage_ix, storage);
    } else {
      br_write_bits(max_bits, symbols[0], storage_ix, storage);
      br_write_bits(max_bits, symbols[1], storage_ix, storage);
      br_write_bits(max_bits, symbols[2], storage_ix, storage);
      br_write_bits(max_bits, symbols[3], storage_ix, storage);
      br_write_bits(1, depth[symbols[0]] == 1 ? 1 : 0, storage_ix, storage);
    }
  } else {
    uint8_t previous_value = 8;
    size_t i;
    store_static_code_length_code(storage_ix, storage);
    for (i = 0; i < length;) {
      const uint8_t value = depth[i];
      size_t reps = 1;
      size_t k;
      for (k = i + 1; k < length && depth[k] == value; ++k) ++reps;
      i += reps;
      if (value == 0) {
        br_write_bits(kZeroRepsDepth[reps], kZeroRepsBits[reps], storage_ix, storage);
      } else {
        if (previous_value != value) {
          br_write_bits(kCodeLengthDepth[value], kCodeLengthBits[value], storage_ix, storage);
          --reps;
        }
        if (reps < 3) {
          while (reps != 0) {
            reps--;
            br_write_bits(kCodeLengthDepth[value], kCodeLengthBits[value], storage_ix, storage);
          }
        } else {
          reps -= 3;
          br_write_bits(kNonZeroRepsDepth[reps], kNonZeroRepsBits[reps], storage_ix, storage);
        }
        previous_value = value;
      }
    }
  }
}

/* ---- context map ---- */

static size_t index_of(const uint8_t* v, size_t v_size, uint8_t value) {
  size_t i = 0;
  for (; i < v_size; ++i) if (v[i] == value) return i;
  return i;
}

static void move_to_front(uint8_t* v, size_t index) {
  uint8_t value = v[index];
  size_t i;
  for (i = index; i != 0; --i) v[i] = v[i - 1];
  v[0] = value;
}

static void move_to_front_transform(const uint32_t* v_in, const size_t v_size, uint32_t* v_out) {
  size_t i;
  uint8_t mtf[256];
  uint32_t max_value;
  if (v_size == 0) return;
  max_value = v_in[0];
  for (i = 1; i < v_size; ++i) if (v_in[i] > max_value) max_value = v_in[i];
  for (i = 0; i <= max_value; ++i) mtf[i] = (uint8_t)i;
  {
    size_t mtf_size = max_value + 1;
    for (i = 0; i < v_size; ++i) {
      size_t index = index_of(mtf, mtf_size, (uint8_t)v_in[i]);
      v_out[i] = (uint32_t)index;
      move_to_front(mtf, index);
    }
  }
}

static void run_length_code_zeros(const size_t in_size, uint32_t* v, size_t* out_size, uint32_t* max_run_length_prefix) {
  uint32_t max_reps = 0;
  size_t i;
  uint32_t max_prefix;
  for (i = 0; i < in_size;) {
    uint32_t reps = 0;
    for (; i < in_size && v[i] != 0; ++i) ;
    for (; i < in_size && v[i] == 0; ++i) ++reps;
    max_reps = BR_MAX(reps, max_reps);
  }
  max_prefix = max_reps > 0 ? br_log2_floor_nonzero(max_reps) : 0;
  max_prefix = BR_MIN(max_prefix, *max_run_length_prefix);
  *max_run_length_prefix = max_prefix;
  *out_size = 0;
  for (i = 0; i < in_size;) {
    if (v[i] != 0) {
      v[*out_size] = v[i] + *max_run_length_prefix;
      ++i;
      ++(*out_size);
    } else {
      uint32_t reps = 1;
      size_t k;
      for (k = i + 1; k < in_size && v[k] == 0; ++k) ++reps;
      i += reps;
      while (reps != 0) {
        if (reps < (2u << max_prefix)) {
          uint32_t run_length_prefix = br_log2_floor_nonzero(reps);
          const uint32_t extra_bits = reps - (1u << run_length_prefix);
          v[*out_size] = run_length_prefix + (extra_bits << 9);
          ++(*out_size);
          break;
        } else {
          const uint32_t extra_bits = (1u << max_prefix) - 1u;
          v[*out_size] = max_prefix + (extra_bits << 9);
          reps -= (2u << max_prefix) - 1u;
          ++(*out_size);
        }
      }
    }
  }
}

#define SYMBOL_BITS 9

static void encode_context_map(const uint32_t* context_map, size_t context_map_size, size_t num_clusters, HuffmanTree* tree, size_t* storage_ix, uint8_t* storage) {
  size_t i;
  uint32_t* rle_symbols;
  uint32_t max_run_length_prefix = 6;
  size_t num_rle_symbols = 0;
  uint32_t histogram[BR_MAX_CONTEXT_MAP_SYMBOLS];
  static const uint32_t kSymbolMask = (1u << SYMBOL_BITS) - 1u;
  uint8_t depths[BR_MAX_CONTEXT_MAP_SYMBOLS];
  uint16_t bits[BR_MAX_CONTEXT_MAP_SYMBOLS];
  store_var_len_uint8(num_clusters - 1, storage_ix, storage);
  if (num_clusters == 1) return;
  rle_symbols = (uint32_t*)malloc(sizeof(uint32_t) * context_map_size);
  move_to_front_transform(context_map, context_map_size, rle_symbols);
  run_length_code_zeros(context_map_size, rle_symbols, &num_rle_symbols, &max_run_length_prefix);
  memset(histogram, 0, sizeof(histogram));
  for (i = 0; i < num_rle_symbols; ++i) ++histogram[rle_symbols[i] & kSymbolMask];
  {
    int use_rle = max_run_length_prefix > 0;
    br_write_bits(1, (uint64_t)use_rle, storage_ix, storage);
    if (use_rle) br_write_bits(4, max_run_length_prefix - 1, storage_ix, storage);
  }
  br_build_and_store_huffman_tree(histogram, num_clusters + max_run_length_prefix, num_clusters + max_run_length_prefix, tree, depths, bits, storage_ix, storage);
  for (i = 0; i < num_rle_symbols; ++i) {
    const uint32_t rle_symbol = rle_symbols[i] & kSymbolMask;
    const uint32_t extra_bits_val = rle_symbols[i] >> SYMBOL_BITS;
    br_write_bits(depths[rle_symbol], bits[rle_symbol], storage_ix, storage);
    if (rle_symbol > 0 && rle_symbol <= max_run_length_prefix) {
      br_write_bits(rle_symbol, extra_bits_val, storage_ix, storage);
    }
  }
  br_write_bits(1, 1, storage_ix, storage);
  free(rle_symbols);
}

static inline void store_block_switch(BlockSplitCode* code, const uint32_t block_len, const uint8_t block_type, int is_first_block, size_t* storage_ix, uint8_t* storage) {
  size_t typecode = next_block_type_code(&code->type_code_calculator, block_type);
  size_t lencode;
  uint32_t len_nextra;
  uint32_t len_extra;
  if (!is_first_block) br_write_bits(code->type_depths[typecode], code->type_bits[typecode], storage_ix, storage);
  get_block_length_prefix_code(block_len, &lencode, &len_nextra, &len_extra);
  br_write_bits(code->length_depths[lencode], code->length_bits[lencode], storage_ix, storage);
  br_write_bits(len_nextra, len_extra, storage_ix, storage);
}

static void build_and_store_block_split_code(const uint8_t* types, const uint32_t* lengths, const size_t num_blocks, const size_t num_types, HuffmanTree* tree, BlockSplitCode* code, size_t* storage_ix, uint8_t* storage) {
  uint32_t type_histo[BR_MAX_BLOCK_TYPE_SYMBOLS];
  uint32_t length_histo[BR_NUM_BLOCK_LEN_SYMBOLS];
  size_t i;
  BlockTypeCodeCalculator type_code_calculator;
  memset(type_histo, 0, (num_types + 2) * sizeof(type_histo[0]));
  memset(length_histo, 0, sizeof(length_histo));
  init_block_type_code_calculator(&type_code_calculator);
  for (i = 0; i < num_blocks; ++i) {
    size_t type_code = next_block_type_code(&type_code_calculator, types[i]);
    if (i != 0) ++type_histo[type_code];
    ++length_histo[block_length_prefix_code(lengths[i])];
  }
  store_var_len_uint8(num_types - 1, storage_ix, storage);
  if (num_types > 1) {
    br_build_and_store_huffman_tree(&type_histo[0], num_types + 2, num_types + 2, tree, &code->type_depths[0], &code->type_bits[0], storage_ix, storage);
    br_build_and_store_huffman_tree(&length_histo[0], BR_NUM_BLOCK_LEN_SYMBOLS, BR_NUM_BLOCK_LEN_SYMBOLS, tree, &code->length_depths[0], &code->length_bits[0], storage_ix, storage);
    store_block_switch(code, lengths[0], types[0], 1, storage_ix, storage);
  }
}

static void store_trivial_context_map(size_t num_types, size_t context_bits, HuffmanTree* tree, size_t* storage_ix, uint8_t* storage) {
  store_var_len_uint8(num_types - 1, storage_ix, storage);
  if (num_types > 1) {
    size_t repeat_code = context_bits - 1u;
    size_t repeat_bits = (1u << repeat_code) - 1u;
    size_t alphabet_size = num_types + repeat_code;
    uint32_t histogram[BR_MAX_CONTEXT_MAP_SYMBOLS];
    uint8_t depths[BR_MAX_CONTEXT_MAP_SYMBOLS];
    uint16_t bits[BR_MAX_CONTEXT_MAP_SYMBOLS];
    size_t i;
    memset(histogram, 0, alphabet_size * sizeof(histogram[0]));
    br_write_bits(1, 1, storage_ix, storage);
    br_write_bits(4, repeat_code - 1, storage_ix, storage);
    histogram[repeat_code] = (uint32_t)num_types;
    histogram[0] = 1;
    for (i = context_bits; i < alphabet_size; ++i) histogram[i] = 1;
    br_build_and_store_huffman_tree(histogram, alphabet_size, alphabet_size, tree, depths, bits, storage_ix, storage);
    for (i = 0; i < num_types; ++i) {
      size_t code = (i == 0 ? 0 : i + context_bits - 1);
      br_write_bits(depths[code], bits[code], storage_ix, storage);
      br_write_bits(depths[repeat_code], bits[repeat_code], storage_ix, storage);
      br_write_bits(repeat_code, repeat_bits, storage_ix, storage);
    }
    br_write_bits(1, 1, storage_ix, storage);
  }
}

typedef struct {
  size_t histogram_length_;
  size_t num_block_types_;
  const uint8_t* block_types_;
  const uint32_t* block_lengths_;
  size_t num_blocks_;
  BlockSplitCode block_split_code_;
  size_t block_ix_;
  size_t block_len_;
  size_t entropy_ix_;
  uint8_t* depths_;
  uint16_t* bits_;
} BlockEncoder;

static void init_block_encoder(BlockEncoder* self, size_t histogram_length, size_t num_block_types, const uint8_t* block_types, const uint32_t* block_lengths, const size_t num_blocks) {
  self->histogram_length_ = histogram_length;
  self->num_block_types_ = num_block_types;
  self->block_types_ = block_types;
  self->block_lengths_ = block_lengths;
  self->num_blocks_ = num_blocks;
  init_block_type_code_calculator(&self->block_split_code_.type_code_calculator);
  self->block_ix_ = 0;
  self->block_len_ = num_blocks == 0 ? 0 : block_lengths[0];
  self->entropy_ix_ = 0;
  self->depths_ = 0;
  self->bits_ = 0;
}

static void cleanup_block_encoder(BlockEncoder* self) { free(self->depths_); free(self->bits_); }

static void build_and_store_block_switch_entropy_codes(BlockEncoder* self, HuffmanTree* tree, size_t* storage_ix, uint8_t* storage) {
  build_and_store_block_split_code(self->block_types_, self->block_lengths_, self->num_blocks_, self->num_block_types_, tree, &self->block_split_code_, storage_ix, storage);
}

static void store_symbol(BlockEncoder* self, size_t symbol, size_t* storage_ix, uint8_t* storage) {
  if (self->block_len_ == 0) {
    size_t block_ix = ++self->block_ix_;
    uint32_t block_len = self->block_lengths_[block_ix];
    uint8_t block_type = self->block_types_[block_ix];
    self->block_len_ = block_len;
    self->entropy_ix_ = block_type * self->histogram_length_;
    store_block_switch(&self->block_split_code_, block_len, block_type, 0, storage_ix, storage);
  }
  --self->block_len_;
  {
    size_t ix = self->entropy_ix_ + symbol;
    br_write_bits(self->depths_[ix], self->bits_[ix], storage_ix, storage);
  }
}

static void store_symbol_with_context(BlockEncoder* self, size_t symbol, size_t context, const uint32_t* context_map, size_t* storage_ix, uint8_t* storage, const size_t context_bits) {
  if (self->block_len_ == 0) {
    size_t block_ix = ++self->block_ix_;
    uint32_t block_len = self->block_lengths_[block_ix];
    uint8_t block_type = self->block_types_[block_ix];
    self->block_len_ = block_len;
    self->entropy_ix_ = (size_t)block_type << context_bits;
    store_block_switch(&self->block_split_code_, block_len, block_type, 0, storage_ix, storage);
  }
  --self->block_len_;
  {
    size_t histo_ix = context_map[self->entropy_ix_ + context];
    size_t ix = histo_ix * self->histogram_length_ + symbol;
    br_write_bits(self->depths_[ix], self->bits_[ix], storage_ix, storage);
  }
}

#define DEFINE_BUILD_AND_STORE_ENTROPY_CODES(Name, Type) \
static void build_and_store_entropy_codes_##Name(BlockEncoder* self, const Type* histograms, const size_t histograms_size, const size_t alphabet_size, HuffmanTree* tree, size_t* storage_ix, uint8_t* storage) { \
  const size_t table_size = histograms_size * self->histogram_length_; \
  self->depths_ = (uint8_t*)malloc(table_size); \
  self->bits_ = (uint16_t*)malloc(table_size * sizeof(uint16_t)); \
  { size_t i; for (i = 0; i < histograms_size; ++i) { size_t ix = i * self->histogram_length_; \
      br_build_and_store_huffman_tree(&histograms[i].data_[0], self->histogram_length_, alphabet_size, tree, &self->depths_[ix], &self->bits_[ix], storage_ix, storage); } } \
}
DEFINE_BUILD_AND_STORE_ENTROPY_CODES(literal, HistogramLiteral)
DEFINE_BUILD_AND_STORE_ENTROPY_CODES(command, HistogramCommand)
DEFINE_BUILD_AND_STORE_ENTROPY_CODES(distance, HistogramDistance)

static void jump_to_byte_boundary(size_t* storage_ix, uint8_t* storage) {
  *storage_ix = (*storage_ix + 7u) & ~7u;
  storage[*storage_ix >> 3] = 0;
}

void br_store_meta_block(const uint8_t* input, size_t start_pos, size_t length, size_t mask, uint8_t prev_byte, uint8_t prev_byte2, int is_last, const BrEncoderParams* params, int literal_context_mode, const Command* commands, size_t n_commands, const MetaBlockSplit* mb, size_t* storage_ix, uint8_t* storage) {
  size_t pos = start_pos;
  size_t i;
  uint32_t num_distance_symbols = params->dist.alphabet_size_max;
  uint32_t num_effective_distance_symbols = params->dist.alphabet_size_limit;
  HuffmanTree* tree;
  BlockEncoder literal_enc, command_enc, distance_enc;
  const BrDistanceParams* dist = &params->dist;
  store_compressed_meta_block_header(is_last, length, storage_ix, storage);
  tree = (HuffmanTree*)malloc(sizeof(HuffmanTree) * MAX_HUFFMAN_TREE_SIZE);
  init_block_encoder(&literal_enc, BR_NUM_LITERAL_SYMBOLS, mb->literal_split.num_types, mb->literal_split.types, mb->literal_split.lengths, mb->literal_split.num_blocks);
  init_block_encoder(&command_enc, BR_NUM_COMMAND_SYMBOLS, mb->command_split.num_types, mb->command_split.types, mb->command_split.lengths, mb->command_split.num_blocks);
  init_block_encoder(&distance_enc, num_effective_distance_symbols, mb->distance_split.num_types, mb->distance_split.types, mb->distance_split.lengths, mb->distance_split.num_blocks);
  build_and_store_block_switch_entropy_codes(&literal_enc, tree, storage_ix, storage);
  build_and_store_block_switch_entropy_codes(&command_enc, tree, storage_ix, storage);
  build_and_store_block_switch_entropy_codes(&distance_enc, tree, storage_ix, storage);
  br_write_bits(2, dist->distance_postfix_bits, storage_ix, storage);
  br_write_bits(4, dist->num_direct_distance_codes >> dist->distance_postfix_bits, storage_ix, storage);
  for (i = 0; i < mb->literal_split.num_types; ++i) br_write_bits(2, (uint64_t)literal_context_mode, storage_ix, storage);
  if (mb->literal_context_map_size == 0) {
    store_trivial_context_map(mb->literal_histograms_size, BR_LITERAL_CONTEXT_BITS, tree, storage_ix, storage);
  } else {
    encode_context_map(mb->literal_context_map, mb->literal_context_map_size, mb->literal_histograms_size, tree, storage_ix, storage);
  }
  if (mb->distance_context_map_size == 0) {
    store_trivial_context_map(mb->distance_histograms_size, BR_DISTANCE_CONTEXT_BITS, tree, storage_ix, storage);
  } else {
    encode_context_map(mb->distance_context_map, mb->distance_context_map_size, mb->distance_histograms_size, tree, storage_ix, storage);
  }
  build_and_store_entropy_codes_literal(&literal_enc, mb->literal_histograms, mb->literal_histograms_size, BR_NUM_LITERAL_SYMBOLS, tree, storage_ix, storage);
  build_and_store_entropy_codes_command(&command_enc, mb->command_histograms, mb->command_histograms_size, BR_NUM_COMMAND_SYMBOLS, tree, storage_ix, storage);
  build_and_store_entropy_codes_distance(&distance_enc, mb->distance_histograms, mb->distance_histograms_size, num_distance_symbols, tree, storage_ix, storage);
  free(tree);
  for (i = 0; i < n_commands; ++i) {
    const Command cmd = commands[i];
    size_t cmd_code = cmd.cmd_prefix_;
    store_symbol(&command_enc, cmd_code, storage_ix, storage);
    store_command_extra(&cmd, storage_ix, storage);
    if (mb->literal_context_map_size == 0) {
      size_t j;
      for (j = cmd.insert_len_; j != 0; --j) {
        store_symbol(&literal_enc, input[pos & mask], storage_ix, storage);
        ++pos;
      }
    } else {
      size_t j;
      for (j = cmd.insert_len_; j != 0; --j) {
        size_t context = br_context(prev_byte, prev_byte2, literal_context_mode);
        uint8_t literal = input[pos & mask];
        store_symbol_with_context(&literal_enc, literal, context, mb->literal_context_map, storage_ix, storage, BR_LITERAL_CONTEXT_BITS);
        prev_byte2 = prev_byte;
        prev_byte = literal;
        ++pos;
      }
    }
    pos += command_copy_len(&cmd);
    if (command_copy_len(&cmd)) {
      prev_byte2 = input[(pos - 2) & mask];
      prev_byte = input[(pos - 1) & mask];
      if (cmd.cmd_prefix_ >= 128) {
        size_t dist_code = cmd.dist_prefix_ & 0x3FF;
        uint32_t distnumextra = cmd.dist_prefix_ >> 10;
        uint64_t distextra = cmd.dist_extra_;
        if (mb->distance_context_map_size == 0) {
          store_symbol(&distance_enc, dist_code, storage_ix, storage);
        } else {
          size_t context = command_distance_context(&cmd);
          store_symbol_with_context(&distance_enc, dist_code, context, mb->distance_context_map, storage_ix, storage, BR_DISTANCE_CONTEXT_BITS);
        }
        br_write_bits(distnumextra, distextra, storage_ix, storage);
      }
    }
  }
  cleanup_block_encoder(&distance_enc);
  cleanup_block_encoder(&command_enc);
  cleanup_block_encoder(&literal_enc);
  if (is_last) jump_to_byte_boundary(storage_ix, storage);
}

static void build_histograms(const uint8_t* input, size_t start_pos, size_t mask, const Command* commands, size_t n_commands, HistogramLiteral* lit_histo, HistogramCommand* cmd_histo, HistogramDistance* dist_histo) {
  size_t pos = start_pos;
  size_t i;
  for (i = 0; i < n_commands; ++i) {
    const Command cmd = commands[i];
    size_t j;
    histogram_add_command(cmd_histo, cmd.cmd_prefix_);
    for (j = cmd.insert_len_; j != 0; --j) {
      histogram_add_literal(lit_histo, input[pos & mask]);
      ++pos;
    }
    pos += command_copy_len(&cmd);
    if (command_copy_len(&cmd) && cmd.cmd_prefix_ >= 128) {
      histogram_add_distance(dist_histo, cmd.dist_prefix_ & 0x3FF);
    }
  }
}

static void store_data_with_huffman_codes(const uint8_t* input, size_t start_pos, size_t mask, const Command* commands, size_t n_commands, const uint8_t* lit_depth, const uint16_t* lit_bits, const uint8_t* cmd_depth, const uint16_t* cmd_bits, const uint8_t* dist_depth, const uint16_t* dist_bits, size_t* storage_ix, uint8_t* storage) {
  size_t pos = start_pos;
  size_t i;
  for (i = 0; i < n_commands; ++i) {
    const Command cmd = commands[i];
    const size_t cmd_code = cmd.cmd_prefix_;
    size_t j;
    br_write_bits(cmd_depth[cmd_code], cmd_bits[cmd_code], storage_ix, storage);
    store_command_extra(&cmd, storage_ix, storage);
    for (j = cmd.insert_len_; j != 0; --j) {
      const uint8_t literal = input[pos & mask];
      br_write_bits(lit_depth[literal], lit_bits[literal], storage_ix, storage);
      ++pos;
    }
    pos += command_copy_len(&cmd);
    if (command_copy_len(&cmd) && cmd.cmd_prefix_ >= 128) {
      const size_t dist_code = cmd.dist_prefix_ & 0x3FF;
      const uint32_t distnumextra = cmd.dist_prefix_ >> 10;
      const uint32_t distextra = cmd.dist_extra_;
      br_write_bits(dist_depth[dist_code], dist_bits[dist_code], storage_ix, storage);
      br_write_bits(distnumextra, distextra, storage_ix, storage);
    }
  }
}

void br_store_meta_block_trivial(const uint8_t* input, size_t start_pos, size_t length, size_t mask, int is_last, const BrEncoderParams* params, const Command* commands, size_t n_commands, size_t* storage_ix, uint8_t* storage) {
  HistogramLiteral lit_histo;
  HistogramCommand cmd_histo;
  HistogramDistance dist_histo;
  uint8_t lit_depth[BR_NUM_LITERAL_SYMBOLS];
  uint16_t lit_bits[BR_NUM_LITERAL_SYMBOLS];
  uint8_t cmd_depth[BR_NUM_COMMAND_SYMBOLS];
  uint16_t cmd_bits[BR_NUM_COMMAND_SYMBOLS];
  uint8_t dist_depth[MAX_SIMPLE_DISTANCE_ALPHABET_SIZE];
  uint16_t dist_bits[MAX_SIMPLE_DISTANCE_ALPHABET_SIZE];
  HuffmanTree* tree;
  uint32_t num_distance_symbols = params->dist.alphabet_size_max;
  store_compressed_meta_block_header(is_last, length, storage_ix, storage);
  clear_histogram_literal(&lit_histo);
  clear_histogram_command(&cmd_histo);
  clear_histogram_distance(&dist_histo);
  build_histograms(input, start_pos, mask, commands, n_commands, &lit_histo, &cmd_histo, &dist_histo);
  br_write_bits(13, 0, storage_ix, storage);
  tree = (HuffmanTree*)malloc(sizeof(HuffmanTree) * MAX_HUFFMAN_TREE_SIZE);
  br_build_and_store_huffman_tree(lit_histo.data_, BR_NUM_LITERAL_SYMBOLS, BR_NUM_LITERAL_SYMBOLS, tree, lit_depth, lit_bits, storage_ix, storage);
  br_build_and_store_huffman_tree(cmd_histo.data_, BR_NUM_COMMAND_SYMBOLS, BR_NUM_COMMAND_SYMBOLS, tree, cmd_depth, cmd_bits, storage_ix, storage);
  br_build_and_store_huffman_tree(dist_histo.data_, MAX_SIMPLE_DISTANCE_ALPHABET_SIZE, num_distance_symbols, tree, dist_depth, dist_bits, storage_ix, storage);
  free(tree);
  store_data_with_huffman_codes(input, start_pos, mask, commands, n_commands, lit_depth, lit_bits, cmd_depth, cmd_bits, dist_depth, dist_bits, storage_ix, storage);
  if (is_last) jump_to_byte_boundary(storage_ix, storage);
}

static void store_static_command_huffman_tree(size_t* storage_ix, uint8_t* storage) {
  br_write_bits(56, 0x92624416307003ull, storage_ix, storage);
  br_write_bits(3, 0, storage_ix, storage);
}

static void store_static_distance_huffman_tree(size_t* storage_ix, uint8_t* storage) {
  br_write_bits(28, 0x0369DC03u, storage_ix, storage);
}

void br_store_meta_block_fast(const uint8_t* input, size_t start_pos, size_t length, size_t mask, int is_last, const BrEncoderParams* params, const Command* commands, size_t n_commands, size_t* storage_ix, uint8_t* storage) {
  uint32_t num_distance_symbols = params->dist.alphabet_size_max;
  uint32_t distance_alphabet_bits = br_log2_floor_nonzero(num_distance_symbols - 1) + 1;
  HuffmanTree* tree = (HuffmanTree*)malloc(sizeof(HuffmanTree) * MAX_HUFFMAN_TREE_SIZE);
  store_compressed_meta_block_header(is_last, length, storage_ix, storage);
  br_write_bits(13, 0, storage_ix, storage);
  if (n_commands <= 128) {
    uint32_t histogram[BR_NUM_LITERAL_SYMBOLS] = {0};
    size_t pos = start_pos;
    size_t num_literals = 0;
    size_t i;
    uint8_t lit_depth[BR_NUM_LITERAL_SYMBOLS];
    uint16_t lit_bits[BR_NUM_LITERAL_SYMBOLS];
    for (i = 0; i < n_commands; ++i) {
      const Command cmd = commands[i];
      size_t j;
      for (j = cmd.insert_len_; j != 0; --j) {
        ++histogram[input[pos & mask]];
        ++pos;
      }
      num_literals += cmd.insert_len_;
      pos += command_copy_len(&cmd);
    }
    br_build_and_store_huffman_tree_fast(tree, histogram, num_literals, 8, lit_depth, lit_bits, storage_ix, storage);
    store_static_command_huffman_tree(storage_ix, storage);
    store_static_distance_huffman_tree(storage_ix, storage);
    store_data_with_huffman_codes(input, start_pos, mask, commands, n_commands, lit_depth, lit_bits, kStaticCommandCodeDepth, kStaticCommandCodeBits, kStaticDistanceCodeDepth, kStaticDistanceCodeBits, storage_ix, storage);
  } else {
    HistogramLiteral lit_histo;
    HistogramCommand cmd_histo;
    HistogramDistance dist_histo;
    uint8_t lit_depth[BR_NUM_LITERAL_SYMBOLS];
    uint16_t lit_bits[BR_NUM_LITERAL_SYMBOLS];
    uint8_t cmd_depth[BR_NUM_COMMAND_SYMBOLS];
    uint16_t cmd_bits[BR_NUM_COMMAND_SYMBOLS];
    uint8_t dist_depth[MAX_SIMPLE_DISTANCE_ALPHABET_SIZE];
    uint16_t dist_bits[MAX_SIMPLE_DISTANCE_ALPHABET_SIZE];
    clear_histogram_literal(&lit_histo);
    clear_histogram_command(&cmd_histo);
    clear_histogram_distance(&dist_histo);
    build_histograms(input, start_pos, mask, commands, n_commands, &lit_histo, &cmd_histo, &dist_histo);
    br_build_and_store_huffman_tree_fast(tree, lit_histo.data_, lit_histo.total_count_, 8, lit_depth, lit_bits, storage_ix, storage);
    br_build_and_store_huffman_tree_fast(tree, cmd_histo.data_, cmd_histo.total_count_, 10, cmd_depth, cmd_bits, storage_ix, storage);
    br_build_and_store_huffman_tree_fast(tree, dist_histo.data_, dist_histo.total_count_, distance_alphabet_bits, dist_depth, dist_bits, storage_ix, storage);
    store_data_with_huffman_codes(input, start_pos, mask, commands, n_commands, lit_depth, lit_bits, cmd_depth, cmd_bits, dist_depth, dist_bits, storage_ix, storage);
  }
  free(tree);
  if (is_last) jump_to_byte_boundary(storage_ix, storage);
}

void br_store_uncompressed_meta_block(int is_final_block, const uint8_t* input, size_t position, size_t mask, size_t len, size_t* storage_ix, uint8_t* storage) {
  size_t masked_pos = position & mask;
  store_uncompressed_meta_block_header(len, storage_ix, storage);
  jump_to_byte_boundary(storage_ix, storage);
  if (masked_pos + len > mask + 1) {
    size_t len1 = mask + 1 - masked_pos;
    memcpy(&storage[*storage_ix >> 3], &input[masked_pos], len1);
    *storage_ix += len1 << 3;
    len -= len1;
    masked_pos = 0;
  }
  memcpy(&storage[*storage_ix >> 3], &input[masked_pos], len);
  *storage_ix += len << 3;
  br_write_bits_prepare_storage(*storage_ix, storage);
  if (is_final_block) {
    br_write_bits(1, 1, storage_ix, storage);
    br_write_bits(1, 1, storage_ix, storage);
    jump_to_byte_boundary(storage_ix, storage);
  }
}
